-- Siembra del «Manual de recursos cognitivos para IntegraMente en Casa»
-- («Manual de recursos para la app 2.docx», entregado el 2026-10-30): 6 de reminiscencia y 27 de
-- atención, memoria y funciones ejecutivas (el manual no trae las 09 ni 11).
-- Generado a partir del documento, no retipeado a mano: texto literal.
-- Se suman a las 34 actividades existentes, que siguen activas.
-- Códigos MRC-NN con el número del manual. Re-ejecutable: actualiza por código.
-- Requiere 20261030000000_recursos_cognicion_enum.sql aplicada antes.

alter table public.media_resources add column if not exists extras jsonb;
comment on column public.media_resources.extras is
  'Material de apoyo estructurado: {modo: tabla|tarjetas, titulo, columnas, filas, intro?, cierre?}. tabla = ejemplos para el familiar; tarjetas = una por vez con «Ver frase completa».';

insert into public.media_resources
  (codigo, titulo, modulo, tipo, tipo_intervencion, dominios, duracion, duracion_min, duracion_max, frecuencia, perfil, requisito, objetivo, materiales, detalle, pasos, progresion, adaptacion, precaucion, ciencia, por_que, niveles_cognitivos, extras, activo)
values
  ($mrc$MRC-01$mrc$, $mrc$Recuerdo el camino$mrc$, 'reminiscencia'::public.resource_modulo, 'actividad'::public.task_tipo, $mrc$reminiscencia$mrc$, array[$mrc$Orientación espacial$mrc$, $mrc$Planificación y Flexibilidad$mrc$, $mrc$Memoria autobiográfica$mrc$, $mrc$Atención$mrc$, $mrc$Lenguaje$mrc$]::text[], $mrc$10 min a 15 min$mrc$, 10, 15, $mrc$De 2 a 3 veces por semana$mrc$, $mrc$Preventivo · Deterioro cognitivo leve. · Demencia Leve$mrc$, $mrc$Preventivo y DCL Utilizar un lugar familiar y permitir pistas visuales o verbales sin exigir precisión.$mrc$, $mrc$Estimular la orientación espacial, la planificación de recorridos y la memoria autobiográfica mediante la descripción de rutas hacia lugares familiares.$mrc$, $mrc$Fotografía de un lugar conocido, como un parque, supermercado, iglesia, lugar significativo para la persona, si está disponible. Sino tienes fotos también pueden conversar sobre un sitio familiar, como la iglesia, el parque o un supermercado cercano, sin necesidad de usar imágenes. Papel y lápiz son opcionales.$mrc$, null, $mrc$["Elijan un lugar que la persona conozca bien. Si tienen una fotografía, pueden utilizarla para iniciar la conversación.", "Pregunten: «¿Cómo llegaríamos desde la casa hasta la iglesia?» o «¿Cuál supermercado queda cerca y por dónde iríamos?».", "Acompañen el recorrido con preguntas sencillas: «¿Por dónde empezamos?», «¿Qué lugares veríamos en el camino?» o «¿Hacia dónde seguimos después?».", "Si les resulta agradable, dibujen juntos un camino sencillo y señalen algunos lugares de referencia."]$mrc$::jsonb, null, $mrc$Ofrezcan una pista o dos opciones: «¿Pasaríamos por el parque o por la escuela?». No hace falta recordar todos los nombres ni describir la ruta con exactitud; lo importante es participar y compartir. El recorrido se realiza mediante la conversación o el dibujo, sin necesidad de salir de casa$mrc$, null, $mrc${"gancho": "¿Sabías que recordar lugares que se frecuentaron a lo largo de la vida puede ayudar a mantener activa la mente?", "evidencia": "Un metaanálisis de Saragih y colaboradores (2022), que incluyó 29 estudios con 3.102 participantes, encontró resultados favorables asociados a esta intervención.", "cierre": "Por eso, hoy vamos a recordar lugares conocidos, pensar cómo llegaríamos hasta ellos y ejercitar nuestra memoria, orientación y lenguaje. 🏡🗺️"}$mrc$::jsonb, $mrc$Favorecer la organización mental de recorridos familiares mediante la identificación de lugares, la descripción de rutas y la evocación de experiencias personales.$mrc$, array['preventivo', 'dcl', 'leve']::text[], null, true),
  ($mrc$MRC-02$mrc$, $mrc$Mi lugar de vivienda antes y ahora$mrc$, 'reminiscencia'::public.resource_modulo, 'actividad'::public.task_tipo, $mrc$reminiscencia$mrc$, array[$mrc$Memoria autobiográfica$mrc$, $mrc$Atención visual$mrc$, $mrc$Lenguaje$mrc$, $mrc$Flexibilidad$mrc$, $mrc$Orientación temporal$mrc$]::text[], $mrc$10–15 minutos$mrc$, 10, 15, $mrc$2–3 veces por semana$mrc$, $mrc$Preventivo. · Deterioro cognitivo leve. · Demencia leve, con apoyo visual y preguntas breves.$mrc$, $mrc$Preventivo, DCL y demencia leve Usar imágenes de lugares realmente familiares cuando sea posible. No discutir para demostrar si un recuerdo es correcto; validar la experiencia y ofrecer ayuda con respeto.$mrc$, $mrc$Evocar recuerdos vinculados con un barrio conocido y comparar, de manera sencilla, cómo era antes y cómo es ahora.$mrc$, $mrc$Fotografías antiguas o actuales del barrio, si están disponibles. También puede realizarse únicamente mediante la conversación, recordando cómo era el lugar.$mrc$, $mrc$Hoy realizaremos «Mi lugar de vivienda antes y ahora». Vamos a recordar un lugar donde la persona haya vivido y compartir algunas historias. Si tienen fotografías, pueden acompañar la conversación; si no, sus recuerdos serán el punto de partida.$mrc$, $mrc$["Elijan un barrio o comunidad que haya sido significativo para la persona.", "Inviten a recordar: «¿Cómo era el lugar donde vivía?», «¿Qué había cerca de su casa?» o «¿Qué le gustaba de ese lugar?».", "Si tienen fotografías, obsérvenlas juntos y conversen sobre los lugares que reconoce.", "Si conoce cómo es el lugar actualmente, pregunten: «¿Qué ha cambiado?» o «¿Qué sigue parecido?». Si no lo sabe, pueden continuar compartiendo recuerdos.", "Cierren retomando algún detalle o historia que haya disfrutado contar."]$mrc$::jsonb, $mrc$Conversar sobre un lugar → recordar un detalle con ayuda → describir una experiencia → comparar el antes y el ahora, si conoce ambos.$mrc$, $mrc$Preventivo: permitir una comparación más libre.
Deterioro cognitivo leve: hacer preguntas concretas.
Demencia leve: presentar una imagen a la vez y ofrecer opciones, por ejemplo: «¿Había más casas o más comercios?». Si el recuerdo genera tristeza o incomodidad, cambiar de tema.$mrc$, null, $mrc${"gancho": "¿Sabías que recordar experiencias del pasado y compartirlas mediante fotografías, preguntas o conversaciones puede ser una forma de mantener la mente activa?", "evidencia": "Una revisión Cochrane realizada por Woods y colaboradores (2018) encontró posibles beneficios de la terapia de reminiscencia en aspectos como la comunicación, la cognición, el estado de ánimo y la calidad de vida, aunque los resultados pueden variar de una persona a otra.", "cierre": "Por eso, hoy vamos a recordar momentos y experiencias significativas, ejercitando nuestra memoria y compartiendo historias de nuestra vida."}$mrc$::jsonb, $mrc$Facilitar la evocación de experiencias vinculadas con un lugar conocido y practicar la observación y comparación de cambios, sin exigir precisión histórica.$mrc$, array['preventivo', 'dcl', 'leve']::text[], null, true),
  ($mrc$MRC-03$mrc$, $mrc$Un día de trabajo, paso a paso$mrc$, 'reminiscencia'::public.resource_modulo, 'actividad'::public.task_tipo, $mrc$reminiscencia$mrc$, array[$mrc$Memoria autobiográfica$mrc$, $mrc$Memoria semántica$mrc$, $mrc$Secuenciación$mrc$, $mrc$Lenguaje$mrc$, $mrc$Atención$mrc$]::text[], $mrc$10–15 minutos$mrc$, 10, 15, $mrc$2–3 veces por semana$mrc$, $mrc$Preventivo. · Deterioro cognitivo leve. · Demencia leve si la persona desea conversar sobre su vida laboral o sus responsabilidades pasadas.$mrc$, $mrc$Adaptar las tarjetas al oficio o responsabilidad real de la persona. No asumir que todas las personas tuvieron un empleo formal; pueden elegirse tareas de cuido, voluntariado o labores del hogar.$mrc$, $mrc$Evocar y organizar la secuencia de tareas de un trabajo, oficio o responsabilidad que haya sido significativa para la persona.$mrc$, $mrc$Tarjetas con dibujos o palabras de acciones relacionadas con el oficio de la persona. Usar tarjetas en blanco para dibujar o escribir las tareas.$mrc$, $mrc$Hoy realizaremos «Un día de trabajo, paso a paso». Hoy vamos a recordar una actividad que la persona realizaba en su trabajo, oficio o responsabilidad cotidiana. Lo importante es conversar y ordenar ideas, no comprobar si recuerda todos los detalles.$mrc$, $mrc$["Preguntar qué trabajo, oficio o responsabilidad le gustaría recordar.", "Invitar a mencionar algunas tareas que realizaba durante una jornada habitual.", "Anotar o dibujar de tres a cinco tareas en tarjetas separadas.", "Pedir que las coloque en un orden aproximado: qué hacía primero, después y al final.", "Conversar sobre qué tarea le resultaba más familiar o qué parte del trabajo disfrutaba, si desea compartirlo."]$mrc$::jsonb, $mrc$Nombrar una tarea → recordar dos tareas → ordenarlas con ayuda → describir una jornada con inicio, desarrollo y cierre.$mrc$, $mrc$Preventivo: dejar que la persona organice las tareas con autonomía.
Deterioro cognitivo leve: usar tres o cuatro tarjetas y preguntas guía.
Demencia leve: elegir entre dos tarjetas por vez y aceptar un orden aproximado. Evitar insistir si el tema laboral es sensible.$mrc$, null, $mrc${"gancho": "¿Sabías que recordar experiencias personales no solo permite revivir momentos importantes, sino que también implica organizar y reconstruir información de nuestra vida?", "evidencia": "Una revisión sistemática publicada en 2025 analizó 83 estudios sobre la memoria autobiográfica en personas con enfermedad de Alzheimer y encontró una relación entre esta memoria y las funciones ejecutivas, que participan en la organización y planificación de la información.", "cierre": "Por eso, hoy vamos a recordar las tareas de un trabajo u oficio y organizarlas paso a paso, ejercitando nuestra memoria, atención, lenguaje y capacidad para ordenar actividades. 🧩💼"}$mrc$::jsonb, $mrc$Apoyar la evocación de conocimientos y experiencias relacionados con un rol significativo y practicar la organización verbal de tareas familiares.$mrc$, array['preventivo', 'dcl', 'leve']::text[], null, true),
  ($mrc$MRC-04$mrc$, $mrc$Palabras y expresiones de mi época$mrc$, 'reminiscencia'::public.resource_modulo, 'actividad'::public.task_tipo, $mrc$reminiscencia$mrc$, array[$mrc$Lenguaje expresivo y comprensivo$mrc$, $mrc$Memoria semántica$mrc$, $mrc$Memoria autobiográfica$mrc$, $mrc$Atención$mrc$, $mrc$Interacción social$mrc$]::text[], $mrc$10–15 minutos$mrc$, 10, 15, $mrc$2–3 veces por semana$mrc$, $mrc$Preventivo. · Deterioro cognitivo leve. · Demencia leve, con ejemplos y opciones de respuesta.$mrc$, $mrc$Elegir expresiones respetuosas y culturalmente familiares. No corregir variantes regionales ni convertir la actividad en un examen de memoria.$mrc$, $mrc$Estimular el lenguaje y la memoria semántica a partir de palabras, dichos o expresiones que la persona utilizaba o escuchaba en otras etapas de su vida.$mrc$, $mrc$Lista breve de expresiones, refranes o palabras propias de la comunidad o generación de la persona. Se pueden preparar tarjetas con una expresión por tarjeta.$mrc$, $mrc$Hoy realizaremos «Palabras y expresiones de mi época». Vamos a recordar palabras o expresiones que se escuchaban antes. No hace falta completar todos los dichos ni saber su origen; podemos conversar sobre lo que significan o cuándo se usaban.$mrc$, $mrc$["Presentar una expresión familiar y leerla en voz alta si hace falta.", "Preguntar si la había escuchado antes y qué cree que significa.", "Invitar a recordar quién la decía o en qué situación se utilizaba, sin exigir que recuerde a una persona específica.", "Si la persona disfruta el reto, comenzar un refrán conocido y dejar que lo complete; también puede elegir entre dos posibles finales.", "Cerrar preguntando si hay otra palabra o expresión que le gustaría compartir."]$mrc$::jsonb, $mrc$Escuchar una expresión → reconocer si resulta familiar → explicar su significado → recordar una situación en la que se utilizaba o completar un refrán conocido.$mrc$, $mrc$Preventivo: explorar significados y variantes regionales.
Deterioro cognitivo leve: ofrecer una pista o ejemplo.
Demencia leve: trabajar con una expresión a la vez y aceptar respuestas cortas, gestos o elecciones entre opciones.$mrc$, null, $mrc${"gancho": "¿Sabías que las palabras que conocemos y su significado forman parte de nuestra memoria semántica, que nos ayuda a comprender el lenguaje y expresar nuestras ideas?", "evidencia": "Una revisión publicada en 2024 sobre intervenciones semánticas en personas mayores destaca la importancia de trabajar con palabras, conceptos y significados mediante actividades estructuradas y conversaciones relacionadas con la vida de cada persona.", "cierre": "Por eso, hoy vamos a recordar dichos, expresiones y palabras familiares, ejercitando nuestro lenguaje, la memoria semántica y la capacidad de expresar nuestros pensamientos. 💬📚"}$mrc$::jsonb, $mrc$Promover la conversación y la recuperación de palabras significativas dentro de un ambiente familiar y sin presión por acertar.$mrc$, array['preventivo', 'dcl', 'leve']::text[], null, true),
  ($mrc$MRC-05$mrc$, $mrc$Organicemos una salida conocida$mrc$, 'reminiscencia'::public.resource_modulo, 'actividad'::public.task_tipo, $mrc$reminiscencia$mrc$, array[$mrc$Planificación$mrc$, $mrc$Secuenciación$mrc$, $mrc$Atención$mrc$, $mrc$Lenguaje$mrc$, $mrc$Memoria autobiográfica$mrc$]::text[], $mrc$10–15 minutos$mrc$, 10, 15, $mrc$2–3 veces por semana$mrc$, $mrc$Deterioro cognitivo leve. · Demencia leve, con preguntas breves y guía del familiar. · Demencia moderada con acompañamiento, si vemos que es un tema que genera angustia cambiarlo$mrc$, $mrc$No pedir a la persona que se desplace ni que demuestre habilidades de orientación en el exterior. Si la actividad despierta preocupación por salir o perderse, cambiar a un ejemplo tranquilo y familiar.$mrc$, $mrc$Practicar la secuenciación y la planificación mental mediante una conversación sobre cómo prepararse para una salida familiar, sin realizar un desplazamiento físico.$mrc$, $mrc$No se necesitan materiales. La actividad se realiza mediante una conversación sobre una salida conocida y significativa para la persona.$mrc$, $mrc$Hoy realizaremos «Organicemos una salida conocida». Vamos a imaginar cómo nos prepararíamos para visitar a alguien, ir al parque o asistir a una actividad que nos guste. Compartiremos ideas y organizaremos los pasos con calma, sin necesidad de salir de casa.$mrc$, $mrc$["Elegir juntos una salida conocida: «Pensemos que vamos a visitar a un familiar. ¿Qué prepararíamos antes de salir?».", "Invitar a mencionar algunas cosas que necesitaría hacer o llevar.", "Ayudar a organizar dos o tres pasos con preguntas como: «¿Qué haríamos primero?» y «¿Qué seguiría después?».", "Si necesita una pista, ofrecer un ejemplo: «Podríamos empezar por vestirnos. ¿Qué haríamos después?».", "Conversar sobre lo que cambiaría según la ocasión: «¿Y si estuviera lloviendo?» o «¿Llevaríamos lo mismo para ir al parque?».", "Cerrar repasando juntos los pasos que mencionaron, sin exigir que los recuerde nuevamente."]$mrc$::jsonb, $mrc$Mencionar algo necesario para salir → organizar dos pasos con ayuda → proponer una secuencia de tres o cuatro pasos → adaptar la preparación a una situación diferente.$mrc$, null, null, $mrc${"gancho": "¿Sabías que las funciones ejecutivas nos ayudan a planificar y organizar pasos?", "evidencia": "Un metaanálisis de 2025 encontró beneficios del entrenamiento cognitivo en algunas habilidades mentales de personas mayores, como la memoria de trabajo y funciones ejecutivas.", "cierre": "Hoy vamos a recordar cómo nos preparábamos para una salida y ordenar sus pasos, ejercitando nuestra planificación, atención y memoria. 🗓️👜"}$mrc$::jsonb, $mrc$Practicar la organización mental de una secuencia cotidiana y evocar estrategias que la persona utilizaba en salidas conocidas.$mrc$, array['dcl', 'leve', 'moderada']::text[], null, true),
  ($mrc$MRC-06$mrc$, $mrc$Una compra de antes$mrc$, 'reminiscencia'::public.resource_modulo, 'actividad'::public.task_tipo, $mrc$reminiscencia$mrc$, array[$mrc$Memoria autobiográfica$mrc$, $mrc$Memoria semántica$mrc$, $mrc$Lenguaje$mrc$, $mrc$Atención$mrc$, $mrc$Secuenciación$mrc$]::text[], $mrc$10–15 minutos$mrc$, 10, 15, $mrc$2–3 veces por semana$mrc$, $mrc$Deterioro cognitivo leve. · Demencia leve · Demencia Moderada$mrc$, $mrc$Elegir productos y comercios relacionados con la experiencia real de la persona. No evaluar cálculo, precios ni capacidad para manejar dinero; el propósito es conversar y recordar.$mrc$, $mrc$Evocar una experiencia de compra cotidiana y organizar verbalmente algunos pasos, productos o decisiones habituales de esa época.$mrc$, $mrc$Fotografías o dibujos de un comercio conocido, una canasta, una lista sencilla y productos habituales de la época o comunidad de la persona. No es necesario utilizar dinero real.$mrc$, $mrc$Hoy realizaremos «Una compra de antes». Vamos a conversar sobre cómo se hacían las compras en una etapa de la vida de la persona. Podemos recordar un lugar, algunos productos y cómo se organizaba la compra, sin necesidad de recordar precios exactos.$mrc$, $mrc$["Preguntar dónde solía hacer las compras: pulpería, feria, mercado, supermercado u otro lugar.", "Invitar a nombrar dos o tres productos que acostumbraba comprar.", "Mostrar una lista o imágenes y pedir que elija cuáles habría incluido en una compra habitual.", "Conversar sobre cómo organizaba la compra: qué necesitaba, cómo llevaba los productos o quién le acompañaba, si desea contarlo.", "Comparar con respeto una costumbre de antes y una de ahora, sin exigir que recuerde fechas o precios."]$mrc$::jsonb, $mrc$Recordar el lugar → nombrar productos → seleccionar imágenes → describir uno o dos pasos de la compra → comparar una costumbre de antes y de ahora.$mrc$, $mrc$Deterioro cognitivo leve: usar una lista breve.
Demencia leve y moderada: presentar dos o tres imágenes a la vez y aceptar señalar en lugar de nombrar. Evitar dinero real, operaciones complejas o situaciones que puedan generar preocupación económica.$mrc$, null, $mrc${"gancho": "¿Sabías que las compras cotidianas requieren recordar productos, prestar atención y organizar información?", "evidencia": "Una revisión científica de 2023, titulada “Virtual reality applications based on instrumental activities of daily living (iADLs) for cognitive intervention in older adults: a systematic review”, analizó cómo actividades simuladas, como comprar en un supermercado, pueden utilizarse para ejercitar habilidades cognitivas.", "cierre": "Hoy vamos a recordar cómo hacíamos las compras antes, qué productos elegíamos y cómo nos organizábamos, estimulando nuestra memoria, atención y lenguaje. 🛒"}$mrc$::jsonb, $mrc$Facilitar la evocación de una actividad cotidiana significativa y practicar la selección y organización verbal de información familiar.$mrc$, array['dcl', 'leve', 'moderada']::text[], null, true),
  ($mrc$MRC-07$mrc$, $mrc$Detectives de detalles$mrc$, 'cognicion'::public.resource_modulo, 'actividad'::public.task_tipo, $mrc$atención, memoria y funciones ejecutivas$mrc$, array[$mrc$Atención selectiva$mrc$, $mrc$Exploración y discriminación visual$mrc$, $mrc$Comprensión verbal$mrc$, $mrc$Memoria semántica, cuando se identifica para qué sirve un objeto$mrc$, $mrc$Velocidad de procesamiento, únicamente en las variantes con reto de rapidez$mrc$]::text[], $mrc$10–15 minutos$mrc$, 10, 15, $mrc$2–3 veces por semana$mrc$, $mrc$Preventivo. · Deterioro cognitivo leve. · Demencia leve. · Demencia moderada, con consignas simples y acompañamiento cercano.$mrc$, $mrc$Evitar imágenes recargadas y letras pequeñas. No medir el éxito por la rapidez; valorar la participación y ajustar la dificultad.$mrc$, $mrc$Estimular la atención selectiva y la exploración visual mediante la búsqueda de objetos del entorno, siguiendo consignas de color, forma o función.$mrc$, $mrc$Objetos que estén a la vista en el lugar donde se encuentra la persona. No se necesitan fotografías, materiales impresos ni preparar un espacio especial.$mrc$, $mrc$Hoy realizaremos «Detectives de detalles». Vamos a descubrir lo que tenemos alrededor, buscando objetos por su color, forma o utilidad. Podemos hacerlo desde donde estamos sentados, señalando o nombrando lo que encontramos. 🔎$mrc$, $mrc$["Observar primero el entorno y elegir una consigna que tenga respuestas visibles.", "Invitar a buscar: «¿Ve algo de color rojo?», «¿Qué objeto tiene forma redonda?» o «¿Qué sirve para sentarse?».", "Dar tiempo para mirar y permitir que responda señalando, nombrando o describiendo el objeto.", "Si necesita ayuda, orientar la búsqueda: «Miremos hacia la mesa» o «Busquemos juntos cerca de la ventana».", "Proponer otra consigna mientras mantenga el interés. No es necesario levantarse ni recoger los objetos."]$mrc$::jsonb, $mrc$Localizar un objeto con ayuda → encontrar un objeto sin ayuda → encontrar varios con una característica común → combinar dos características → añadir un reto de rapidez, únicamente si resulta adecuado y agradable.$mrc$, $mrc$Preventivo: proponer un reto como «Encuentre cinco objetos de color blanco lo más rápido que pueda» o «Busque tres objetos redondos». Comprobar primero que haya suficientes objetos visibles. Si resulta sencillo, combinar características: «Algo rojo que sirva para cocinar». La rapidez es opcional.
Deterioro cognitivo leve: pedir dos o tres objetos con una misma característica, utilizando una consigna a la vez. Repetirla cuando sea necesario y evitar la presión de tiempo.
Demencia leve: buscar un objeto por ronda con indicaciones concretas: «Señale algo rojo» o «¿Qué sirve para sentarse?». Ofrecer pistas sobre dónde mirar.
Demencia moderada: elegir un objeto visible y cercano, reducir las distracciones y acompañar con gestos. Por ejemplo: «Busquemos la silla», señalando hacia la zona donde está. Si hace falta, mostrar dos objetos y preguntar «¿Cuál sirve para tomar agua?». Aceptar la mirada dirigida, el gesto o el señalamiento como formas de participación.$mrc$, null, $mrc${"gancho": "¿Sabías que la atención nos ayuda a encontrar detalles importantes?", "evidencia": "Una investigación publicada en 2023 encontró beneficios del entrenamiento cognitivo para la atención en personas mayores con deterioro cognitivo.", "cierre": "Hoy vamos a explorar nuestro entorno y descubrir detalles cotidianos, practicando la atención y la observación visual. 🔎"}$mrc$::jsonb, $mrc$Practicar la búsqueda de objetos cotidianos a partir de una consigna, ajustando la complejidad y el apoyo a las capacidades de la persona.$mrc$, array['preventivo', 'dcl', 'leve', 'moderada']::text[], null, true),
  ($mrc$MRC-08$mrc$, $mrc$Clasifiquemos por categorías$mrc$, 'cognicion'::public.resource_modulo, 'actividad'::public.task_tipo, $mrc$atención, memoria y funciones ejecutivas$mrc$, array[$mrc$Razonamiento$mrc$, $mrc$Flexibilidad cognitiva$mrc$, $mrc$Lenguaje$mrc$, $mrc$Memoria semántica$mrc$, $mrc$Atención$mrc$]::text[], $mrc$5–15 minutos, ajustables al interés y tolerancia.$mrc$, 5, 15, $mrc$2 veces por semana como orientación, según el plan individual.$mrc$, $mrc$Deterioro cognitivo leve. · Demencia leve. · Demencia moderada, con objetos familiares y acompañamiento.$mrc$, $mrc$Actividad con objetos disponibles en casa; no requiere imágenes ni tarjetas. Mostrar al familiar la variante correspondiente. Ajustar cantidad de objetos, categorías y apoyo según la respuesta de la persona. Aceptar clasificaciones alternativas razonables. En demencia moderada, mantener un único criterio y evitar exigir explicaciones. Si aparece dificultad, reducir objetos y modelar un ejemplo.$mrc$, $mrc$Practicar la clasificación de objetos cotidianos según sus características o utilidad, ajustando la complejidad y el acompañamiento a las capacidades de la persona.$mrc$, $mrc$Objetos disponibles en casa, colocados sobre una mesa: prendas de vestir, frutas, verduras o utensilios seguros, por ejemplo. Elegir objetos limpios, fáciles de reconocer y suficientemente grandes. No utilizar elementos cortantes, medicamentos, productos de limpieza ni piezas pequeñas$mrc$, $mrc$Hoy realizaremos «Clasifiquemos por categorías». Vamos a organizar algunos objetos de casa y descubrir qué tienen en común. Podemos agruparlos por su utilidad, por el lugar donde se guardan o por alguna de sus características. 🧩$mrc$, $mrc$["Elegir los objetos y colocarlos al alcance de la persona, sobre una superficie despejada.", "Explicar una consigna concreta: «Vamos a poner los alimentos de este lado y la ropa de este otro».", "Mostrar un ejemplo si necesita ayuda y permitir que continúe colocando o señalando los objetos.", "Cuando termine, comentar juntos cómo quedaron los grupos. Si le resulta cómodo, preguntar: «¿Qué tienen en común?».", "Si la tarea resulta sencilla, proponer una clasificación más específica o cambiar el criterio, según las adaptaciones siguientes."]$mrc$::jsonb, $mrc$Separar dos grupos con ayuda → clasificar sin ayuda → formar subcategorías → reorganizar los mismos objetos con otro criterio → proponer una forma diferente de agruparlos.$mrc$, $mrc$Deterioro cognitivo leve: utilizar entre ocho y doce objetos, según tolerancia. Pedir una clasificación inicial y luego cambiar la regla. Por ejemplo, agrupar prendas por tipo —camisas, pantalones y medias— y después reorganizarlas según se utilicen para clima frío o caliente. Invitar a explicar el criterio y proponer otra manera de organizarlas.
Demencia leve: utilizar entre seis y ocho objetos familiares. Comenzar con dos categorías y, si resulta sencillo, trabajar subcategorías: separar frutas de verduras o camisas de medias. También pueden clasificar por el lugar donde se guardan. Ofrecer una consigna a la vez y mostrar un ejemplo cuando sea necesario.
Demencia moderada: comenzar con cuatro objetos de dos categorías claramente diferentes, como dos prendas y dos alimentos conocidos. Decir: «La ropa va aquí y la comida va aquí», señalando cada espacio y colocando un ejemplo. Entregar un objeto a la vez si necesita más apoyo. Aceptar que señale dónde colocarlo, sin exigir que nombre la categoría ni explique su elección.$mrc$, null, $mrc${"gancho": "¿Sabías que reconocer para qué sirven los objetos y qué tienen en común utiliza nuestros conocimientos sobre el mundo?", "evidencia": "Clasificarlos permite practicar la memoria semántica y la atención. Cuando cambiamos la regla para organizarlos, también ponemos en juego la flexibilidad cognitiva.", "cierre": "Hoy vamos a organizar objetos cotidianos, reconociendo semejanzas y explorando distintas maneras de agruparlos. 🧩"}$mrc$::jsonb, $mrc$Favorecer la organización de conceptos y la capacidad de reconocer semejanzas entre elementos cotidianos.$mrc$, array['dcl', 'leve', 'moderada']::text[], null, true),
  ($mrc$MRC-10$mrc$, $mrc$Un recorrido para recordar$mrc$, 'cognicion'::public.resource_modulo, 'actividad'::public.task_tipo, $mrc$atención, memoria y funciones ejecutivas$mrc$, array[$mrc$Memoria episódica verbal$mrc$, $mrc$Aprendizaje asociativo$mrc$, $mrc$Imaginación visual$mrc$, $mrc$Organización de la información$mrc$, $mrc$Atención$mrc$]::text[], $mrc$10–15 minutos, ajustables al interés y tolerancia.$mrc$, 10, 15, $mrc$2–3 veces por semana como orientación, según el plan individual.$mrc$, $mrc$Preventivo. · Deterioro cognitivo leve, cuando la persona comprenda la estrategia y pueda imaginar las asociaciones con acompañamiento.$mrc$, $mrc$Actividad verbal e imaginativa, sin desplazamiento físico ni materiales adicionales. Mostrar las instrucciones y el ejemplo al familiar. Mantener el mismo recorrido durante cada práctica y una palabra por lugar. No cambiar ni retirar palabras mientras se está aprendiendo la estrategia. Ofrecer pistas y repasar las asociaciones cuando sea necesario. No utilizar como evaluación clínica. Simplificar o cambiar de recurso si genera confusión o frustración.$mrc$, $mrc$Practicar una estrategia de memoria que consiste en asociar palabras con lugares conocidos de la casa, utilizando imágenes mentales llamativas para facilitar su recuerdo.$mrc$, $mrc$No se necesitan imágenes ni tarjetas. El familiar leerá una lista breve de palabras y acompañará la creación de un recorrido imaginario por una casa conocida.$mrc$, $mrc$Hoy realizaremos «Un recorrido para recordar». Vamos a imaginar que colocamos algunas palabras en distintos lugares de la casa. Para recordarlas, crearemos escenas divertidas y exageradas: ¡una naranja del tamaño de un sillón puede resultar difícil de olvidar!$mrc$, $mrc$["Elegir dos o tres lugares de una casa que la persona conozca bien, siguiendo un orden sencillo: puerta de entrada → sala → cocina.", "Comenzar con dos o tres palabras, colocando mentalmente una en cada lugar.", "Imaginar juntos una escena llamativa que una cada palabra con su lugar. Puede tener un tamaño exagerado, movimiento o un sonido divertido.", "Repasar el recorrido y las escenas en el mismo orden.", "Invitar a recorrer nuevamente la casa en su imaginación: «¿Qué habíamos imaginado en la puerta? ¿Y en la sala?».", "Si necesita ayuda, recordar parte de la escena y reconstruirla juntos."]$mrc$::jsonb, $mrc$Asociar dos palabras con dos lugares y ayuda → recordar tres asociaciones → crear sus propias escenas → ampliar hasta cuatro o cinco palabras, si maneja la estrategia con comodidad.$mrc$, $mrc$Preventivo: comenzar con tres palabras e invitar a crear sus propias asociaciones. Aumentar gradualmente hasta cinco, manteniendo un lugar distinto para cada palabra.
Deterioro cognitivo leve: comenzar con dos palabras y dos lugares muy conocidos. Construir las escenas juntos, repetir el recorrido y ofrecer pistas. Aumentar la cantidad únicamente si comprende y disfruta la estrategia. Si imaginar las escenas resulta difícil, elegir otro recurso más concreto.$mrc$, null, $mrc${"gancho": "¿Sabías que relacionar información nueva con lugares conocidos puede ayudarnos a recordarla?", "evidencia": "Esta estrategia se llama método de los lugares o método de loci. Utiliza un recorrido familiar como guía para organizar la información y recuperarla después.", "cierre": "Hoy vamos a unir palabras con lugares de una casa conocida, utilizando nuestra imaginación para practicar una forma de aprender y recordar. 🏡🧠"}$mrc$::jsonb, $mrc$Aprender y practicar una estrategia para recordar una lista breve mediante asociaciones entre palabras, escenas imaginadas y lugares familiares.$mrc$, array['preventivo', 'dcl']::text[], $mrc${"modo": "tabla", "titulo": "Ejemplo para practicar", "columnas": ["Lugar del recorrido", "Escena que imaginaremos"], "filas": [["Puerta de entrada", "Un pan gigante bloquea la puerta y huele a recién horneado."], ["Sala", "Un sombrero enorme salta sobre el sillón."], ["Cocina", "Una naranja del tamaño de una pelota rueda sobre la mesa."]], "intro": "Vamos a recordar estas tres palabras: pan, sombrero y naranja.", "cierre": "Después, preguntar: «Volvamos a recorrer la casa en nuestra imaginación. ¿Qué había en la entrada? ¿Qué encontramos en la sala? ¿Y en la cocina?»."}$mrc$::jsonb, true),
  ($mrc$MRC-12$mrc$, $mrc$¿Qué necesitamos llevar?$mrc$, 'cognicion'::public.resource_modulo, 'actividad'::public.task_tipo, $mrc$atención, memoria y funciones ejecutivas$mrc$, array[$mrc$Memoria semántica$mrc$, $mrc$Comprensión verbal$mrc$, $mrc$Razonamiento práctico$mrc$, $mrc$Elección entre alternativas$mrc$, $mrc$Lenguaje expresivo, cuando se responde verbalmente$mrc$]::text[], $mrc$5–10 minutos, ajustables al interés y tolerancia.$mrc$, 5, 10, $mrc$2–3 veces por semana como orientación, según el plan individual.$mrc$, $mrc$Demencia leve. · Demencia moderada, con opciones concretas y acompañamiento del familiar.$mrc$, $mrc$Asignar a demencia leve y moderada según comprensión y apoyo requerido. Mostrar al familiar las situaciones, posibles respuestas y opciones de ayuda. Actividad principalmente verbal, con objetos reales como apoyo opcional. Aceptar respuestas alternativas que sean útiles para la situación. Alternar la posición de la opción adecuada al leer las alternativas. Evitar situaciones desconocidas o que generen angustia. No utilizar las respuestas para determinar si la persona puede salir sola o tomar decisiones de seguridad.$mrc$, $mrc$Estimular la elección de objetos útiles para situaciones cotidianas mediante preguntas sencillas y familiares.$mrc$, $mrc$No se necesitan materiales. La actividad se realiza mediante una conversación. Si facilita la comprensión, pueden mostrar dos objetos disponibles en casa para que la persona elija.$mrc$, $mrc$Hoy realizaremos «¿Qué necesitamos llevar?». Vamos a imaginar situaciones conocidas, como salir un día lluvioso o visitar la playa, y conversar sobre lo que nos sería útil llevar. Podemos pensar juntos y ofrecer opciones cuando haga falta. ☂️🏖️$mrc$, $mrc$["Elegir una situación que resulte conocida para la persona.", "Hacer una pregunta breve: «Si salimos y está lloviendo, ¿qué podríamos llevar para protegernos de la lluvia?».", "Dar tiempo para responder y aceptar distintas ideas útiles.", "Si necesita ayuda, ofrecer dos opciones: «¿Una sombrilla o una toalla de baño?».", "Comentar la utilidad de su elección: «Sí, la sombrilla nos ayuda a protegernos de la lluvia».", "Continuar con otra situación mientras mantenga el interés."]$mrc$::jsonb, $mrc$Elegir entre dos objetos u opciones → responder sin opciones → mencionar otro objeto útil → explicar brevemente para qué lo llevaría.$mrc$, $mrc$Demencia leve: comenzar con una pregunta abierta y concreta. Si responde con facilidad, invitar a mencionar otro objeto o su utilidad: «¿Qué más llevaríamos?» o «¿Para qué nos serviría?». Ofrecer opciones si lo necesita.
Demencia moderada: presentar una situación a la vez con una frase corta. Ofrecer dos opciones claramente diferenciadas desde el inicio si resulta necesario. Pueden mostrar objetos reales y aceptar que responda señalando, mirando o tomando el objeto. No exigir que explique su elección.$mrc$, null, $mrc${"gancho": "¿Sabías que reconocer qué objetos necesitamos utiliza nuestros conocimientos sobre su función?", "evidencia": "Relacionar una sombrilla con la lluvia o un abrigo con el frío pone en juego la memoria semántica, la comprensión del lenguaje y el razonamiento cotidiano.", "cierre": "Hoy vamos a conversar sobre situaciones conocidas y elegir objetos útiles, practicando nuestras habilidades con el apoyo que necesitemos. 💡"}$mrc$::jsonb, $mrc$Favorecer la participación en elecciones sencillas y el reconocimiento de la utilidad de objetos cotidianos, ajustando las preguntas y la ayuda a las capacidades de la persona.$mrc$, array['leve', 'moderada']::text[], $mrc${"modo": "tabla", "titulo": "Ejemplos para conversar", "columnas": ["Situación y pregunta", "Posibles respuestas para orientar al familiar", "Apoyo si necesita ayuda"], "filas": [["Está lloviendo y vamos a salir. ¿Qué podemos llevar para protegernos?", "Sombrilla, capa o impermeable.", "«¿Una sombrilla o una toalla de baño?»."], ["Vamos a la playa. ¿Qué podemos llevar para protegernos del sol?", "Sombrero, bloqueador solar, sombrilla o ropa que proteja del sol.", "«¿Un sombrero o una bufanda de lana?»."], ["Vamos a un lugar donde hace frío. ¿Qué ropa podríamos llevar?", "Suéter, abrigo o chaqueta.", "«¿Un abrigo o un traje de baño?»."], ["Vamos a pasar el día fuera. ¿Qué podemos llevar para tomar cuando tengamos sed?", "Agua o una bebida habitual adecuada para la persona.", "«¿Una botella de agua o un peine?»."], ["Vamos a caminar y necesitamos calzarnos. ¿Qué nos pondríamos en los pies?", "Zapatos cómodos o tenis.", "«¿Unos zapatos o unos guantes?»."], ["Vamos a comprar algunos alimentos. ¿Qué podemos llevar para traerlos?", "Bolsa, canasta o carrito de compras.", "«¿Una bolsa o una almohada?»."]]}$mrc$::jsonb, true),
  ($mrc$MRC-13$mrc$, $mrc$Completemos el refrán$mrc$, 'cognicion'::public.resource_modulo, 'actividad'::public.task_tipo, $mrc$atención, memoria y funciones ejecutivas$mrc$, array[$mrc$Lenguaje expresivo y comprensivo$mrc$, $mrc$Memoria semántica$mrc$, $mrc$Acceso a palabras y expresiones conocidas$mrc$, $mrc$Atención verbal$mrc$]::text[], $mrc$5–15 minutos, según interés y tolerancia. No es necesario completar todas las tarjetas.$mrc$, 5, 15, $mrc$1–2 veces por semana como orientación, según el plan individual.$mrc$, $mrc$Preventivo. · Deterioro cognitivo leve. · Demencia leve, con pistas verbales y guía del familiar.$mrc$, $mrc$Recurso independiente de la actividad 04, clasificado en lenguaje. Mostrar una tarjeta a la vez con el inicio del refrán y un botón «Ver frase completa». Al desplegarla, mostrar la pregunta de conversación. Incluir botones «Anterior» y «Siguiente». La respuesta es oral, sin puntuación ni límite de tiempo. Aceptar variantes regionales y ofrecer pistas. Si un refrán no resulta familiar, pasar a otro.$mrc$, $mrc$Estimular el lenguaje y la memoria semántica mediante la continuación de refranes conocidos y la conversación sobre su significado.$mrc$, $mrc$Tarjetas digitales disponibles en la app con el inicio de diez refranes y la opción de mostrar la frase completa. No se necesitan materiales impresos.$mrc$, $mrc$Hoy realizaremos «Completemos el refrán». Vamos a escuchar el inicio de algunos refranes e intentar recordar cómo siguen. Si alguno no viene a la mente, podemos completarlo juntos y conversar sobre su significado.$mrc$, $mrc$["Abrir una tarjeta y leer el inicio del refrán, por ejemplo: «Al que madruga…».", "Preguntar «¿cómo seguía?» y dar tiempo para responder.", "Si necesita ayuda, ofrecer una pista, como «Dios le…», o mostrar la frase completa y leerla juntos.", "Conversar sobre su significado: «¿Qué cree que significa?» o «¿En qué situación lo usaría?».", "Si surge algún recuerdo, preguntar «¿lo había escuchado antes?» o «¿quién acostumbraba decirlo?».", "Continuar con otro refrán mientras la persona disfrute la actividad."]$mrc$::jsonb, $mrc$Escuchar el refrán completo → completarlo con una pista → completarlo sin ayuda → explicar su significado o mencionar una situación en la que se utiliza.$mrc$, $mrc$Preventivo: invitar a completar el refrán y proponer un ejemplo de uso.
Deterioro cognitivo leve: ofrecer pistas verbales y hacer una pregunta a la vez.
Demencia leve: elegir refranes familiares, decirlos juntos y utilizar ejemplos concretos. Aceptar respuestas breves sin exigir explicaciones del significado.$mrc$, null, $mrc${"gancho": "¿Sabías que las palabras, las expresiones conocidas y sus significados forman parte de nuestra memoria semántica?", "evidencia": "Una revisión publicada en 2024 por Folia y Silva describe enfoques de intervención centrados en palabras y significados, considerando las características de cada persona.", "cierre": "Hoy vamos a completar refranes conocidos y conversar sobre lo que significan, ejercitando nuestro lenguaje y la memoria semántica. 💬📚"}$mrc$::jsonb, $mrc$Facilitar la recuperación de expresiones familiares y la comprensión de sus significados mediante una conversación agradable y sin presión por acertar.$mrc$, array['preventivo', 'dcl', 'leve']::text[], $mrc${"modo": "tarjetas", "titulo": "Tarjetas de refranes", "columnas": ["Inicio del refrán", "Continuación", "Pregunta para conversar"], "filas": [["Al que madruga…", "Dios le ayuda.", "¿Qué cree que significa?"], ["Camarón que se duerme…", "se lo lleva la corriente.", "¿En qué situación lo usaría?"], ["Más vale maña…", "que fuerza.", "¿Puede pensar en un ejemplo?"], ["Poco a poco…", "se llena el saco.", "¿Qué quiere decir este refrán?"], ["No hay mal…", "que por bien no venga.", "¿Qué cree que significa?"], ["A caballo regalado…", "no se le mira el colmillo.", "¿Cuándo se suele decir?"], ["El que mucho abarca…", "poco aprieta.", "¿Qué consejo nos da este refrán?"], ["Más sabe el diablo por viejo…", "que por diablo.", "¿Qué significa para usted?"], ["En casa de herrero…", "cuchillo de palo.", "¿En qué situación podría utilizarse?"], ["Más vale pájaro en mano…", "que cien volando.", "¿Qué cree que quiere decir?"]]}$mrc$::jsonb, true),
  ($mrc$MRC-14$mrc$, $mrc$Mi memoria tiene un plan$mrc$, 'cognicion'::public.resource_modulo, 'actividad'::public.task_tipo, $mrc$atención, memoria y funciones ejecutivas$mrc$, array[$mrc$Organización$mrc$, $mrc$Planificación$mrc$, $mrc$Atención al registrar información$mrc$, $mrc$Reconocimiento de las propias necesidades de apoyo$mrc$, $mrc$Uso de estrategias para recordar pendientes$mrc$]::text[], $mrc$5–10 minutos para preparar el sistema y unos minutos para la consulta diaria.$mrc$, 5, 10, $mrc$Consulta diaria y revisión semanal de su utilidad.$mrc$, $mrc$Preventivo. · Deterioro cognitivo leve, con acompañamiento cuando sea necesario.$mrc$, $mrc$Mostrar instrucciones y un ejemplo de pendiente. No requiere escribir información personal en la app. No pedir un registro exhaustivo de olvidos ni utilizarlos como puntuación de deterioro. Registrar también las estrategias que funcionan. Simplificar si genera preocupación o resulta difícil de mantener.$mrc$, $mrc$Reconocer una dificultad cotidiana de memoria y practicar el uso de una agenda o libreta para organizar pendientes.$mrc$, $mrc$Una libreta o agenda y un lápiz. También puede utilizarse el calendario del celular si la persona lo maneja con facilidad. Elegir un solo medio para anotar los pendientes.$mrc$, $mrc$Hoy realizaremos «Mi memoria tiene un plan». Vamos a elegir algo que cuesta recordar y buscar una manera de facilitarlo. Anotar y revisar nuestros pendientes puede ayudarnos a organizarnos. 📝$mrc$, $mrc$["Conversar sobre algo que se haya olvidado recientemente: «¿Hubo algo que quería hacer y se le pasó?». Elegir un solo ejemplo.", "Escribirlo en una frase corta: «Se me olvidó llamar a mi hermana».", "Anotar cuándo podría hacerlo: «Mañana, después del desayuno, llamar a mi hermana».", "Dejar la agenda en un lugar visible y acordar un momento para consultarla cada día. Por ejemplo: después del desayuno.", "Al revisar la agenda, realizar el pendiente o decidir cuándo hacerlo. Marcarlo cuando esté terminado.", "Después de unos días, conversar: «¿Nos ayudó tenerlo anotado? ¿Qué podemos cambiar para que sea más fácil?»."]$mrc$::jsonb, $mrc$Anotar un pendiente con ayuda → consultar la agenda en un momento fijo → registrar y revisar pendientes con mayor autonomía → ajustar el sistema según lo que resulte útil.$mrc$, $mrc$Preventivo: registrar sus propios pendientes y elegir un momento diario para revisar la agenda.
Deterioro cognitivo leve: utilizar una agenda sencilla, con letra clara y pocos pendientes por día. El familiar puede acompañar la escritura y la consulta, procurando que la persona participe.$mrc$, null, $mrc${"gancho": "¿Sabías que una agenda puede funcionar como un apoyo para la memoria?", "evidencia": "Un ensayo de Greenaway, Duncan y Smith (2013) encontró beneficios en el funcionamiento cotidiano y en la confianza para manejar dificultades de memoria después de un entrenamiento estructurado con calendario y libreta en personas con deterioro cognitivo leve amnésico.", "cierre": "Hoy vamos a practicar cómo anotar y consultar nuestros pendientes para facilitar la organización diaria. 📝"}$mrc$::jsonb, $mrc$Establecer un hábito de registro y consulta que facilite el manejo de tareas cotidianas.$mrc$, array['preventivo', 'dcl']::text[], null, true),
  ($mrc$MRC-15$mrc$, $mrc$Cuando ocurra esto, haré aquello$mrc$, 'cognicion'::public.resource_modulo, 'actividad'::public.task_tipo, $mrc$atención, memoria y funciones ejecutivas$mrc$, array[$mrc$Memoria prospectiva$mrc$, $mrc$Planificación$mrc$, $mrc$Atención a señales del entorno$mrc$, $mrc$Asociación entre una situación y una acción$mrc$]::text[], $mrc$5–10 minutos para preparar el plan y una revisión breve después de ponerlo en práctica.$mrc$, 5, 10, $mrc$Practicar con un pendiente por día, según necesidad.$mrc$, $mrc$Preventivo. · Deterioro cognitivo leve, con una sola asociación y acompañamiento cuando sea necesario.$mrc$, $mrc$Mostrar instrucciones y el ejemplo de la frase. Comenzar con una sola asociación entre señal y acción. Elegir tareas de bajo riesgo. Mantener las notas, alarmas y apoyos necesarios. No utilizar como sustituto de supervisión para medicación u otras tareas que impliquen seguridad.$mrc$, $mrc$Practicar el recuerdo de una tarea futura asociándola con un momento o una señal concreta de la rutina.$mrc$, $mrc$No se necesitan materiales. Puede utilizarse una nota visible como apoyo.$mrc$, $mrc$Hoy realizaremos «Cuando ocurra esto, haré aquello». Vamos a practicar un truco para recordar un pendiente: unirlo con algo que hacemos todos los días. 📌$mrc$, $mrc$["Elegir algo sencillo que se quiera recordar. Por ejemplo: dejar listo un libro que hay que devolver.", "Elegir un momento de la rutina para hacerlo, como terminar el desayuno.", "Decir juntos la frase: «Cuando termine de desayunar, pondré el libro junto a mi bolso».", "Imaginar ese momento: terminar de desayunar, buscar el libro y colocarlo junto al bolso.", "Poner en práctica el plan la próxima vez que llegue ese momento. Si hace falta, dejar una nota visible que diga: «Poner el libro junto al bolso».", "Después, conversar sobre si el plan ayudó. Si no funcionó, elegir otro momento o añadir un recordatorio."]$mrc$::jsonb, $mrc$Preparar una frase con ayuda → realizar una tarea con la señal elegida y un recordatorio → utilizar la estrategia con mayor autonomía → aplicarla a otro pendiente.$mrc$, $mrc$Preventivo: elegir una tarea, construir su propia frase y valorar qué momento de la rutina resulta más útil.
Deterioro cognitivo leve: preparar la frase con acompañamiento. Elegir una señal evidente y una acción sencilla que pueda realizarse inmediatamente después. Practicar con un solo pendiente a la vez.$mrc$, null, $mrc${"gancho": "¿Sabías que decidir cuándo y en qué situación haremos algo puede ayudarnos a recordarlo?", "evidencia": "Esta estrategia se llama intención de implementación y consiste en unir una señal con una acción: «Cuando pase esto, haré aquello». Estudios en personas mayores han encontrado beneficios para determinadas tareas de memoria prospectiva, que es la capacidad de recordar hacer algo más adelante.", "cierre": "Hoy vamos a transformar un pendiente en un plan concreto, eligiendo cuándo lo haremos. 📌"}$mrc$::jsonb, $mrc$Practicar una estrategia que facilite recordar y realizar una tarea cotidiana en el momento previsto.$mrc$, array['preventivo', 'dcl']::text[], null, true),
  ($mrc$MRC-16$mrc$, $mrc$Lo recuerdo después$mrc$, 'cognicion'::public.resource_modulo, 'actividad'::public.task_tipo, $mrc$atención, memoria y funciones ejecutivas$mrc$, array[$mrc$Aprendizaje de información nueva$mrc$, $mrc$Memoria episódica$mrc$, $mrc$Recuperación de información$mrc$, $mrc$Atención$mrc$]::text[], $mrc$5–10 minutos.$mrc$, 5, 10, $mrc$2–3 veces por semana como orientación, retomando el mismo dato mientras sea útil.$mrc$, $mrc$Preventivo. · Deterioro cognitivo leve, con acompañamiento y pausas ajustadas a su respuesta.$mrc$, $mrc$Mostrar instrucciones y ejemplo al familiar. Los intervalos son orientativos: no es necesario llegar a dos minutos. Ampliar la pausa solo cuando el recuerdo sea cómodo. Ante dificultad, dar la respuesta y acortar el intervalo. No mostrar puntuaciones ni interpretar el desempeño como evaluación clínica. Finalizar si aparece cansancio o incomodidad.$mrc$, $mrc$Practicar el aprendizaje de un dato útil mediante intentos de recuerdo separados por pausas breves y ajustadas a la persona.$mrc$, $mrc$Un dato breve que la persona quiera aprender y un reloj o temporizador opcional.$mrc$, $mrc$Hoy realizaremos «Lo recuerdo después». Vamos a practicar cómo recordar un dato nuevo, haciendo pequeñas pausas. El familiar acompañará la actividad y ofrecerá ayuda cuando sea necesario. 🧠$mrc$, $mrc$["Elegir un dato útil, como el nombre de una persona nueva: Elena.", "Decir el dato y repetirlo juntos: «La persona se llama Elena».", "Conversar de otra cosa durante unos 30 segundos. Después preguntar: «¿Cómo se llama la persona?».", "Si lo recuerda con facilidad, esperar un minuto antes de volver a preguntar. Después pueden probar con dos minutos. Durante las pausas, continuar conversando.", "Si no lo recuerda, dar la respuesta con naturalidad: «Se llama Elena. Digámoslo juntos: Elena». Volver a preguntar después de una pausa más corta.", "Terminar después de unos pocos intentos, repasando juntos el dato."]$mrc$::jsonb, $mrc$Repetir el dato juntos → recordarlo después de unos segundos → ampliar poco a poco la pausa → practicar el mismo dato en otra ocasión.$mrc$, $mrc$Preventivo: elegir un dato nuevo y aumentar las pausas gradualmente, siempre que lo recuerde con comodidad.
Deterioro cognitivo leve: comenzar con repetición inmediata y pausas de pocos segundos si hace falta. Trabajar un solo dato. Cuando no lo recuerde, proporcionar la respuesta y practicar nuevamente con una pausa más corta.$mrc$, null, $mrc${"gancho": "¿Sabías que practicar el recuerdo en distintos momentos es una estrategia de aprendizaje?", "evidencia": "La recuperación espaciada consiste en intentar recordar una información después de pequeñas pausas, ajustando el tiempo según la respuesta. Esta estrategia se ha investigado en personas con deterioro cognitivo leve, incluyendo un ensayo aleatorizado del programa digital USMART publicado en 2017.", "cierre": "Hoy vamos a practicar un dato útil en pequeños pasos, con el tiempo y la ayuda que necesitemos. 🧠"}$mrc$::jsonb, $mrc$Favorecer el aprendizaje de un dato concreto mediante práctica distribuida y ayuda adaptada.$mrc$, array['preventivo', 'dcl']::text[], null, true),
  ($mrc$MRC-17$mrc$, $mrc$Un lugar para mis cosas$mrc$, 'cognicion'::public.resource_modulo, 'actividad'::public.task_tipo, $mrc$atención, memoria y funciones ejecutivas$mrc$, array[$mrc$Atención$mrc$, $mrc$Asociación entre un objeto y su ubicación$mrc$, $mrc$Aprendizaje de una rutina cotidiana$mrc$, $mrc$Uso de apoyos externos para la memoria$mrc$, $mrc$Participación funcional$mrc$]::text[], $mrc$De 5 a 10 minutos. En demencia moderada o severa, realizar una práctica más breve según disposición y tolerancia.$mrc$, 5, 10, $mrc$Practicar en los momentos habituales de uso del objeto, sin repetir innecesariamente.$mrc$, $mrc$Preventivo. · Deterioro cognitivo leve. · Demencia leve, con indicaciones breves y apoyos. · Demencia moderada, con acompañamiento directo. · Demencia severa, únicamente en la versión de participación guiada, sin exigir recuerdo posterior.$mrc$, $mrc$Elegir la adaptación según las capacidades actuales. Mantener un objeto y una ubicación al inicio. En demencia moderada y severa, acompañamiento directo. En severa, omitir la búsqueda y la exigencia de recuerdo.$mrc$, $mrc$Practicar una rutina para guardar y localizar un objeto cotidiano mediante una ubicación fija y apoyos visuales o verbales.$mrc$, $mrc$Un objeto cotidiano y seguro, como los lentes, su estuche o el control remoto. Una bandeja o recipiente fácil de identificar. Opcionalmente, una fotografía del objeto para señalar dónde guardarlo.$mrc$, $mrc$Hoy realizaremos «Un lugar para mis cosas». Vamos a elegir un lugar fijo para un objeto que la persona utilice con frecuencia y practicar juntos cómo guardarlo y encontrarlo. Pueden comenzar con los lentes o el control remoto. 🏡$mrc$, $mrc$["Elijan un objeto que la persona utilice habitualmente.", "Acuerden un lugar visible, accesible y cercano a donde suele usarlo. Coloquen una bandeja para identificar ese espacio.", "Muestren la acción mientras dicen: «Vamos a guardar los lentes en esta bandeja».", "Inviten a la persona a colocar el objeto. Si puede, pídanle que acompañe la acción con una frase: «Mis lentes quedan en la bandeja».", "Después de una conversación breve, invítenla a buscarlo: «Vamos a buscar los lentes». Si necesita ayuda, señalen la bandeja o acompáñenla hasta el lugar.", "Al terminar de usarlo, guárdenlo nuevamente en el mismo sitio. Practiquen esta rutina en los momentos habituales del día."]$mrc$::jsonb, $mrc$Guardar un objeto con demostración → guardarlo con una indicación → localizarlo utilizando la señal visual → practicar la rutina con menos ayuda, si resulta posible.
Incorporar un segundo objeto únicamente cuando la primera rutina resulte familiar. Mantener las señales que sigan siendo útiles.$mrc$, $mrc$Ofrezcan una indicación concreta: «Mire, aquí está la bandeja de los lentes». Si hace falta, muestren nuevamente la acción y háganla juntos. No es necesario que recuerde la ubicación sin ayuda para poder participar.

Preventivo: permitir que la persona elija el lugar y explique por qué le resulta práctico. Practicar la rutina y, posteriormente, incorporar otro objeto si lo desea.
Deterioro cognitivo leve: trabajar con un objeto por vez. Utilizar una señal visible y acompañar la acción con una frase breve. Mantener la misma ubicación entre prácticas.
Demencia leve: mostrar primero qué hacer y dar una indicación por vez. Señalar el lugar cuando sea necesario y acompañar la búsqueda sin hacer preguntas repetidas para comprobar si recuerda.
Demencia moderada: presentar un objeto y la bandeja a la vista. Decir: «Pongamos el control aquí», acompañando con un gesto. El familiar participa durante toda la actividad.
Demencia severa: invitar a participar en una acción breve, como colocar juntos un objeto en la bandeja. Aceptar que participe mirando, tocando o acompañando el movimiento voluntariamente. Omitir la búsqueda posterior y las preguntas de recuerdo.$mrc$, $mrc$No esconder el objeto ni cambiarlo de lugar para aumentar la dificultad. Evitar medicamentos, dinero, documentos importantes u objetos peligrosos. Todos los familiares deben respetar la ubicación elegida. Si aparecen frustración, cansancio o rechazo, ofrecer ayuda, simplificar o terminar la actividad.$mrc$, $mrc${"gancho": "¿Sabías que practicar una tarea cotidiana con apoyos puede ayudar a realizarla con mayor facilidad?", "evidencia": "Una revisión Cochrane de 2023 encontró que la rehabilitación cognitiva personalizada puede mejorar el desempeño en las actividades específicamente trabajadas en personas con demencia leve o moderada.", "cierre": "Inspirándonos en este enfoque, hoy vamos a practicar una rutina concreta: guardar un objeto en el mismo lugar y utilizar las ayudas que necesitemos para encontrarlo. 🧠"}$mrc$::jsonb, $mrc$Facilitar que la persona participe en guardar y localizar un objeto cotidiano en un lugar fijo, con los apoyos que necesite. En demencia severa, favorecer la participación acompañada en la acción de guardar, sin exigir aprendizaje de la ubicación.$mrc$, array['preventivo', 'dcl', 'leve', 'moderada', 'avanzada']::text[], null, true),
  ($mrc$MRC-18$mrc$, $mrc$Recordamos una noticia breve$mrc$, 'cognicion'::public.resource_modulo, 'actividad'::public.task_tipo, $mrc$atención, memoria y funciones ejecutivas$mrc$, array[$mrc$Comprensión verbal$mrc$, $mrc$Atención auditiva$mrc$, $mrc$Memoria de información reciente$mrc$, $mrc$Organización de ideas$mrc$, $mrc$Expresión oral$mrc$]::text[], $mrc$De 5 a 10 minutos; reducir en demencia moderada.$mrc$, 5, 10, $mrc$De 2 a 3 veces por semana, variando los temas.$mrc$, $mrc$Preventivo. · Deterioro cognitivo leve. · Demencia leve, con información breve y apoyos. · Demencia moderada, mediante una versión simplificada de comprensión inmediata.$mrc$, $mrc$Elegir un tema de interés. Ajustar la extensión y permitir repetición. En demencia moderada, trabajar comprensión inmediata.$mrc$, $mrc$Practicar la comprensión y el recuerdo de información breve mediante una conversación sobre un tema de interés.$mrc$, $mrc$Una noticia positiva o un texto breve sobre un tema que le interese a la persona: naturaleza, deportes, cultura o acontecimientos de su comunidad. Puede leerse en papel o contarse oralmente.$mrc$, $mrc$Hoy realizaremos «Recordamos una noticia breve». Vamos a compartir una información interesante y conversar sobre sus ideas principales. Elijan un tema que la persona disfrute. 📰$mrc$, $mrc$["Elijan un texto de tres o cuatro frases, con una idea principal clara.", "Expliquen el tema antes de comenzar: «Voy a leerle una noticia sobre un jardín de mariposas».", "Lean despacio y hagan una pausa al terminar.", "Inviten a comentar: «¿De qué trataba?» o «¿Qué le llamó la atención?».", "Si necesita ayuda, aporten una pista: «Hablaba de un lugar donde viven…».", "Vuelvan a leer la información si lo desea y reconstruyan juntos la idea principal."]$mrc$::jsonb, $mrc$Comprender una frase → comentar la idea principal de un texto breve → recordar algún detalle → retomar la información después de una conversación corta.$mrc$, $mrc$Ofrezcan dos opciones relacionadas con el contenido: «¿La noticia hablaba de mariposas o de peces?». También pueden decir una parte y permitir que complete: «En el jardín había muchas…».

Preventivo: utilizar textos algo más extensos y pedir que explique la noticia con sus propias palabras.
Deterioro cognitivo leve: trabajar con tres o cuatro frases y recuperar primero la idea principal. Permitir releer.
Demencia leve: presentar una o dos frases, acompañadas de una imagen si resulta útil. Ofrecer preguntas concretas y opciones.
Demencia moderada: compartir una sola frase sobre algo visible o familiar y comentarla inmediatamente. Omitir el recuerdo después de una pausa.
Demencia severa: no utilizar esta actividad en su formato de comprensión y recuerdo de noticias.$mrc$, $mrc$Evitar noticias alarmantes, violentas o que generen preocupación. No exigir fechas, nombres o detalles secundarios. Verificar que la persona escuche y comprenda la lectura.$mrc$, $mrc${"gancho": "Compartir información y conversar sobre ella permite combinar comprensión, atención y memoria en una interacción significativa. Los programas de estimulación cognitiva incluyen conversaciones y actividades variadas.", "evidencia": "", "cierre": "Hoy vamos a escuchar, comprender y comentar una información que nos interese."}$mrc$::jsonb, $mrc$Facilitar que la persona identifique o reconstruya la idea principal de una información breve, con la ayuda necesaria.$mrc$, array['preventivo', 'dcl', 'leve', 'moderada']::text[], null, true),
  ($mrc$MRC-19$mrc$, $mrc$La historia de dos objetos$mrc$, 'cognicion'::public.resource_modulo, 'actividad'::public.task_tipo, $mrc$atención, memoria y funciones ejecutivas$mrc$, array[$mrc$Asociación semántica$mrc$, $mrc$Aprendizaje de información$mrc$, $mrc$Lenguaje$mrc$, $mrc$Atención$mrc$, $mrc$Imaginación, cuando resulte accesible$mrc$]::text[], $mrc$De 5 a 10 minutos.$mrc$, 5, 10, $mrc$De 2 a 3 veces por semana.$mrc$, $mrc$Preventivo. · Deterioro cognitivo leve. · Demencia leve, con modelado y objetos visibles.$mrc$, $mrc$Comenzar con dos objetos y una relación concreta. En demencia leve, priorizar el apoyo visible y el modelado.$mrc$, $mrc$Practicar la asociación de información mediante una frase que relacione dos objetos cotidianos.$mrc$, $mrc$De dos a cuatro objetos cotidianos seguros, como una taza, una cuchara, un sombrero o un libro.$mrc$, $mrc$Hoy realizaremos «La historia de dos objetos». Vamos a unir dos objetos mediante una frase sencilla. Podemos inventar una situación cotidiana o una historia divertida. ☕📖$mrc$, $mrc$["Coloquen dos objetos sobre la mesa, por ejemplo una taza y un libro.", "Observen y nombren cada uno. Si no aparece el nombre, proporciónenlo con naturalidad.", "Propongan una frase que los relacione: «Me tomo un café mientras leo el libro».", "Inviten a la persona a repetir la idea con sus propias palabras o a proponer otra.", "Mantengan los objetos visibles y conversen brevemente sobre la escena.", "Si resulta cómodo, cubran uno y utilicen la frase como pista para recordarlo. Si no lo recuerda, muéstrenlo y reconstruyan juntos la relación."]$mrc$::jsonb, $mrc$Relacionar dos objetos visibles → crear una frase propia → recordar un objeto con ayuda de la frase → enlazar tres objetos, si resulta sencillo.$mrc$, $mrc$Comiencen la frase: «Para revolver el café de la taza utilizo una…». Acepten una palabra, un gesto o el señalamiento del objeto.

Preventivo: crear asociaciones propias e incorporar un tercer objeto. Puede imaginar la escena si le resulta natural.
Deterioro cognitivo leve: trabajar con dos objetos y una relación concreta. Repetir la misma asociación antes de cambiarla.
Demencia leve: el familiar propone una frase breve y la persona completa, señala o representa la acción. Mantener los objetos visibles si cubrirlos genera dificultad.
Demencia moderada o severa: no utilizar la versión de aprendizaje asociativo y recuerdo. Para estos niveles, elegir actividades de reconocimiento y uso acompañado de objetos.$mrc$, $mrc$No insistir en crear imágenes mentales si le resulta difícil. Evitar asociaciones demasiado abstractas y objetos pequeños o peligrosos.$mrc$, $mrc${"gancho": "¿Sabías que relacionar algo nuevo con algo conocido puede ayudarnos a recordarlo?", "evidencia": "Al unir dos objetos mediante una frase, les damos un significado que puede servirnos de pista para recordar después.", "cierre": "Hoy vamos a practicar esta estrategia con objetos de la casa. Es una forma sencilla de aprender a crear conexiones que también podemos utilizar en nuestra memoria cotidiana. 🧠"}$mrc$::jsonb, $mrc$Facilitar que la persona establezca una relación entre dos objetos y la utilice como apoyo durante la actividad.$mrc$, array['preventivo', 'dcl', 'leve']::text[], null, true),
  ($mrc$MRC-20$mrc$, $mrc$Escuchemos una palabra especial$mrc$, 'cognicion'::public.resource_modulo, 'actividad'::public.task_tipo, $mrc$atención, memoria y funciones ejecutivas$mrc$, array[$mrc$Atención auditiva selectiva$mrc$, $mrc$Atención sostenida$mrc$, $mrc$Comprensión de instrucciones$mrc$, $mrc$Mantenimiento de una regla sencilla$mrc$]::text[], $mrc$De 3 a 8 minutos.$mrc$, 3, 8, $mrc$De 2 a 3 veces por semana.$mrc$, $mrc$Preventivo. · Deterioro cognitivo leve. · Demencia leve, si comprende y mantiene una regla sencilla. · Demencia moderada, únicamente en la versión de palabra y objeto visible.$mrc$, $mrc$Una palabra y una respuesta al inicio. No puntuar ni exigir velocidad. En demencia moderada, utilizar la versión inmediata con objeto visible.$mrc$, $mrc$Practicar la atención auditiva y la identificación de una palabra dentro de una lectura breve.$mrc$, $mrc$Un texto breve preparado por el familiar y un objeto que represente la palabra elegida, si se necesita apoyo. Ejemplo: elegir la palabra «café» y leer: «En la mañana preparé café. Abrí la ventana y puse la mesa. El café estaba listo».$mrc$, $mrc$Hoy realizaremos «Escuchemos una palabra especial». Vamos a escuchar un texto corto y hacer una señal cuando aparezca la palabra elegida. Pueden señalar un objeto, levantar un dedo o decir «aquí». 👂$mrc$, $mrc$["Elijan una palabra familiar que aparezca dos o tres veces en el texto.", "Acuerden una respuesta cómoda: «Cuando escuche “café”, señale esta taza».", "Hagan un ensayo con una frase corta.", "Lean lentamente, con pausas naturales.", "Si la persona pierde la regla, recuérdenla y vuelvan a practicar juntos.", "Terminen comentando el contenido, sin contabilizar errores."]$mrc$::jsonb, $mrc$Identificar la palabra en una frase → mantener la regla durante varias frases → escuchar un texto un poco más largo.$mrc$, $mrc$Dejen el objeto visible y hagan la señal junto con la persona. Reduzcan el texto a una frase por vez.

Preventivo: ampliar gradualmente el texto o elegir una categoría, como nombres de frutas, si la primera versión resulta fácil.
Deterioro cognitivo leve: mantener una sola palabra y una señal visible.
Demencia leve: utilizar frases cortas y recordar la regla antes de cada una cuando sea necesario.
Demencia moderada: mostrar el objeto y decir una frase que lo incluya: «Aquí está la taza». Invitar a mirarlo o señalarlo. No exigir que mantenga una regla durante un relato.
Demencia severa: no utilizar esta actividad como detección de palabras.$mrc$, $mrc$Realizar en un ambiente tranquilo y comprobar que escuche adecuadamente. Evitar sonidos fuertes, respuestas rápidas obligatorias o palmadas si producen dolor o sobresalto.$mrc$, $mrc${"gancho": "¿Sabías que la atención nos ayuda a identificar lo que nos interesa entre todo lo que escuchamos?", "evidencia": "La utilizamos, por ejemplo, cuando seguimos una conversación aunque haya otros sonidos alrededor. Hoy vamos a practicar esta habilidad escuchando una palabra especial dentro de un relato y haciendo una señal cada vez que aparezca. Una manera sencilla de ejercitar la escucha y la concentración. 👂🧠 Un ejemplo para practicar Lean el siguiente párrafo en voz alta, a un ritmo natural y sin destacar la palabra elegida. Cada vez que la persona escuche «café», deberá hacer la señal que acordaron: levantar un dedo, señalar una taza o decir «aquí». “El domingo por la mañana, Elena decidió preparar café antes de que llegara su familia. Mientras el agua se calentaba, abrió las ventanas y acomodó unas flores en el centro de la mesa. Había comprado pan en la panadería del barrio y tenía lista una bandeja con frutas. Al poco rato llegó su hermana, quien comentó que el aroma del café se sentía desde la entrada. Las dos conversaron sobre una vecina que había comenzado a cultivar tomates en su jardín. Después llegaron los nietos, dejaron sus abrigos en una silla y salieron al patio a buscar al perro. Elena sirvió el café y se sentó junto a la ventana para escuchar las historias de la semana. Su hermana contó que había encontrado unas fotografías antiguas mientras ordenaba un armario. Todos se acercaron a mirarlas y reconocieron la casa donde pasaban las vacaciones. Entre recuerdos y risas, alguien preguntó si todavía quedaba café. Elena señaló la jarra y siguió contando la historia de aquella tarde en que una fuerte lluvia los había dejado sin electricidad”. Cómo crear sus propios párrafos", "cierre": "Elijan una palabra conocida, como «pan», «perro» o «jardín», e inclúyanla varias veces en una historia. Intercalen frases que no la contengan y eviten colocarla siempre en posiciones predecibles. Pueden inspirarse en situaciones cotidianas o temas que la persona disfrute."}$mrc$::jsonb, $mrc$Facilitar que la persona identifique la palabra acordada durante una lectura breve, con apoyos cuando sean necesarios.$mrc$, array['preventivo', 'dcl', 'leve', 'moderada']::text[], null, true),
  ($mrc$MRC-21$mrc$, $mrc$Preparemos la mesa juntos$mrc$, 'cognicion'::public.resource_modulo, 'actividad'::public.task_tipo, $mrc$atención, memoria y funciones ejecutivas$mrc$, array[$mrc$Atención dirigida$mrc$, $mrc$Comprensión de instrucciones$mrc$, $mrc$Reconocimiento de objetos$mrc$, $mrc$Organización espacial$mrc$, $mrc$Participación funcional$mrc$]::text[], $mrc$De 5 a 10 minutos; reducir a una interacción breve en demencia severa.$mrc$, 5, 10, $mrc$Integrar en una rutina habitual, según disposición.$mrc$, $mrc$Demencia leve. · Demencia moderada, con instrucciones de un paso. · Demencia severa, mediante una acción acompañada y voluntaria.$mrc$, $mrc$Objetos seguros, instrucciones breves y acompañamiento según necesidad. En demencia severa, priorizar participación voluntaria.$mrc$, $mrc$Practicar la atención durante una tarea cotidiana mediante la selección y colocación de objetos.$mrc$, $mrc$Mantel individual, servilleta, cuchara y vaso plástico vacío. Utilizar únicamente elementos seguros.$mrc$, $mrc$Hoy realizaremos «Preparemos la mesa juntos». Vamos a organizar algunos objetos para compartir una tarea del hogar. Cada persona puede participar haciendo una parte. 🍽️$mrc$, $mrc$["Coloquen sobre una mesa los objetos que van a utilizar.", "Expliquen: «Vamos a preparar este espacio para la merienda».", "Inviten a elegir un elemento: «Busquemos la servilleta».", "Pidan colocarlo en un lugar concreto, señalando si hace falta.", "Continúen con los demás objetos, uno por uno.", "Revisen juntos lo preparado y agradezcan su colaboración."]$mrc$::jsonb, $mrc$Colocar un objeto con demostración → seguir una indicación → completar un puesto → preparar dos puestos utilizando un modelo.$mrc$, $mrc$Muestren el objeto y el lugar: «Esta servilleta va aquí». Pueden preparar un puesto como modelo para que la persona lo observe.

Demencia leve: entregar una indicación por vez y señalar dónde colocar cada elemento.
Demencia moderada: ofrecer directamente el objeto y una instrucción breve: «Ponga la servilleta aquí».
Demencia severa: invitar a una sola acción, como dejar una servilleta sobre la mesa, si puede y desea hacerlo. Aceptar otras formas de participación sin forzar el movimiento.$mrc$, $mrc$Realizar sentado si es más seguro. Evitar cuchillos, vidrio, bebidas calientes y alimentos durante el ejercicio si no se han considerado las necesidades de alimentación y deglución.$mrc$, $mrc${"gancho": "¿Sabías que preparar la mesa pone en juego varias habilidades al mismo tiempo?", "evidencia": "Buscar la servilleta, elegir los utensilios y decidir dónde colocarlos nos permite utilizar la atención, comprender indicaciones y organizar el espacio.", "cierre": "Hoy vamos a aprovechar esta tarea cotidiana para ejercitar estas habilidades y compartir un momento en familia. Cada persona puede colaborar a su manera, con la ayuda que necesite. 🍽️🧠"}$mrc$::jsonb, $mrc$Favorecer que la persona complete una parte de la preparación de la mesa con el apoyo adecuado.$mrc$, array['leve', 'moderada', 'avanzada']::text[], null, true),
  ($mrc$MRC-22$mrc$, $mrc$Describamos sin decir el nombre$mrc$, 'cognicion'::public.resource_modulo, 'actividad'::public.task_tipo, $mrc$atención, memoria y funciones ejecutivas$mrc$, array[$mrc$Memoria semántica$mrc$, $mrc$Acceso a palabras$mrc$, $mrc$Descripción$mrc$, $mrc$Comprensión verbal$mrc$, $mrc$Comunicación mediante gestos y palabras$mrc$]::text[], $mrc$De 5 a 10 minutos.$mrc$, 5, 10, $mrc$De 2 a 3 veces por semana.$mrc$, $mrc$Preventivo. · Deterioro cognitivo leve. · Demencia leve. · Demencia moderada, con objetos visibles y preguntas concretas.$mrc$, $mrc$Aceptar diferentes formas de respuesta. Ajustar la cantidad de objetos y ofrecer modelos.$mrc$, $mrc$Practicar la descripción de objetos mediante sus características, usos y relaciones.$mrc$, $mrc$De tres a cinco objetos cotidianos seguros o fotografías claras: peine, taza, zapato, sombrero o cuchara.$mrc$, $mrc$Hoy realizaremos «Describamos sin decir el nombre». Vamos a dar pistas sobre objetos conocidos. Podemos contar para qué sirven, cómo son o dónde los utilizamos. 🗣️$mrc$, $mrc$["El familiar comienza con un ejemplo: «Sirve para peinarse y puede tener un mango».", "Inviten a la persona a nombrar o señalar el objeto.", "Muestren otro y propongan describirlo: «¿Para qué lo usamos?» o «¿Cómo es?».", "Si resulta cómodo, alternen los turnos para dar y escuchar pistas.", "Cuando no aparezca una palabra, acepten una descripción o un gesto y aporten el nombre con naturalidad."]$mrc$::jsonb, $mrc$Reconocer un objeto por su uso → describir una característica → dar varias pistas → describir sin tenerlo a la vista, si resulta accesible.$mrc$, $mrc$Ofrezcan una frase para completar: «La cuchara sirve para…». También pueden presentar dos objetos y pedir que señale el que corresponde a la descripción.

Preventivo: describir sin decir el nombre y utilizar pistas más variadas.
Deterioro cognitivo leve: mantener el objeto visible y orientar con preguntas sobre su función, forma o lugar de uso.
Demencia leve: trabajar con objetos muy familiares y aceptar frases breves, gestos o señalamiento.
Demencia moderada: presentar uno o dos objetos y preguntar por una función concreta: «¿Cuál usamos para peinarnos?».
Demencia severa: no utilizar el juego de adivinación. Elegir una propuesta de comunicación acompañada con objetos familiares.$mrc$, $mrc$Evitar que se convierta en una prueba de vocabulario. No insistir en obtener el nombre exacto si la persona logra comunicar el significado.$mrc$, $mrc${"gancho": "¿Sabías que podemos explicar qué es un objeto aunque no nos salga su nombre?", "evidencia": "Al describir para qué sirve, cómo es o dónde lo usamos, ponemos en práctica nuestros conocimientos y buscamos otras maneras de comunicar lo que queremos decir.", "cierre": "Hoy vamos a jugar con estas pistas para ejercitar el lenguaje. Porque describir, señalar o hacer un gesto también nos ayuda a expresar una idea y mantener la conversación. 🗣️🧠"}$mrc$::jsonb, $mrc$Facilitar que la persona comunique una característica o función de un objeto, utilizando palabras, gestos o señalamiento.$mrc$, array['preventivo', 'dcl', 'leve', 'moderada']::text[], null, true),
  ($mrc$MRC-23$mrc$, $mrc$Elijamos y conversemos$mrc$, 'cognicion'::public.resource_modulo, 'actividad'::public.task_tipo, $mrc$atención, memoria y funciones ejecutivas$mrc$, array[$mrc$Comprensión de opciones$mrc$, $mrc$Expresión de preferencias$mrc$, $mrc$Comunicación verbal y no verbal$mrc$, $mrc$Turnos de interacción$mrc$, $mrc$Participación en decisiones cotidianas$mrc$]::text[], $mrc$De 3 a 10 minutos, según la interacción.$mrc$, 3, 10, $mrc$Integrar en oportunidades cotidianas, sin convertir cada decisión en un ejercicio.$mrc$, $mrc$Demencia leve. · Demencia moderada, con opciones visibles. · Demencia severa, si puede expresar aceptación, rechazo o elección mediante una respuesta reconocible.$mrc$, $mrc$Ofrecer opciones reales. Dar tiempo y confirmar la respuesta. En demencia severa, no atribuir significado definitivo a una señal aislada.$mrc$, $mrc$Facilitar la expresión de preferencias y el intercambio comunicativo mediante opciones concretas.$mrc$, $mrc$Dos objetos, fotografías o alternativas reales: dos prendas, dos canciones o dos actividades posibles.$mrc$, $mrc$Hoy realizaremos «Elijamos y conversemos». Vamos a ofrecer opciones y dar espacio para expresar lo que cada persona prefiere. Se puede responder hablando, señalando, mirando o haciendo un gesto. 💬$mrc$, $mrc$["Elijan una decisión sencilla que pueda respetarse, como qué música escuchar.", "Presenten las dos opciones: «¿Prefiere escuchar esta canción o esta otra?».", "Den tiempo para responder, evitando repetir enseguida la pregunta.", "Confirmen la elección: «Entiendo que prefiere esta. ¿La escuchamos?».", "Si puede y desea conversar, pregunten qué le gusta de esa opción.", "Realicen la actividad elegida cuando sea posible."]$mrc$::jsonb, $mrc$Expresar aceptación o rechazo → elegir entre dos opciones → explicar una preferencia → mantener una conversación breve sobre la elección.$mrc$, $mrc$Presenten una opción por vez y observen la respuesta. Si no es clara, no supongan una preferencia: vuelvan a ofrecerla de forma sencilla o prueben en otro momento.

Demencia leve: utilizar preguntas breves y confirmar lo que ha expresado.
Demencia moderada: presentar dos objetos reales, uno junto al otro, y aceptar señalamiento o gestos.
Demencia severa: presentar una opción por vez. Considerar la mirada o el movimiento como posibles señales que deben confirmarse con su respuesta habitual y el contexto. Respetar el rechazo y detenerse si aparece malestar.$mrc$, $mrc$Ofrecer elecciones reales y apropiadas. No utilizar esta actividad para tomar decisiones clínicas, económicas o de consentimiento complejo. Una respuesta ambigua no debe interpretarse automáticamente como aceptación.$mrc$, $mrc${"gancho": "¿Sabías que elegir qué música escuchar o qué ropa ponerse también es una oportunidad para comunicarnos?", "evidencia": "Al ofrecer opciones, damos espacio para comprender, expresar gustos y participar en las decisiones del día a día.", "cierre": "Hoy vamos a practicar cómo expresar y escuchar esas preferencias. Las palabras, los gestos y el señalamiento pueden ayudarnos a comunicar una elección. Lo importante es dar tiempo para responder, confirmar lo que la persona quiere y respetar su decisión. 💬🧠"}$mrc$::jsonb, $mrc$Facilitar que la persona exprese una preferencia o una respuesta de aceptación o rechazo y que el familiar la reconozca y respete.$mrc$, array['leve', 'moderada', 'avanzada']::text[], null, true),
  ($mrc$MRC-24$mrc$, $mrc$Escucho, hago y compruebo$mrc$, 'cognicion'::public.resource_modulo, 'actividad'::public.task_tipo, $mrc$atención, memoria y funciones ejecutivas$mrc$, array[$mrc$Memoria de trabajo$mrc$, $mrc$Atención auditiva$mrc$, $mrc$Comprensión verbal$mrc$, $mrc$Secuenciación de acciones$mrc$, $mrc$Revisión de lo realizado$mrc$]::text[], $mrc$De 5 a 10 minutos; reducir en demencia moderada.$mrc$, 5, 10, $mrc$De 2 a 3 veces por semana.$mrc$, $mrc$Preventivo. · Deterioro cognitivo leve. · Demencia leve, con instrucciones sencillas. · Demencia moderada, mediante una acción inmediata con demostración.$mrc$, $mrc$Comenzar con una acción. Aumentar los pasos únicamente si resulta cómodo. Permitir repetición y demostración.$mrc$, $mrc$Practicar el mantenimiento de una instrucción breve mientras se realiza una acción con objetos cotidianos.$mrc$, $mrc$Una servilleta, una cuchara, un vaso plástico y una bandeja. Utilizar objetos seguros y fáciles de manipular.$mrc$, $mrc$Hoy realizaremos «Escucho, hago y compruebo». Vamos a escuchar una indicación, realizarla y revisar juntos lo que hicimos. Pueden practicar sentados frente a una mesa. 🥄$mrc$, $mrc$["Coloquen los objetos sobre la mesa, al alcance de la persona.", "Expliquen: «Voy a decirle algo que haremos con estos objetos».", "Comiencen con una indicación: «Ponga la cuchara en la bandeja».", "Antes de actuar, inviten a repetir o señalar lo que va a hacer, si le resulta posible.", "Permitan que complete la acción sin apresurarla.", "Revisen juntos: «La cuchara quedó en la bandeja».", "Si resulta sencillo, propongan dos acciones: «Ponga la cuchara en la bandeja y después coloque la servilleta junto al vaso»."]$mrc$::jsonb, $mrc$Realizar una acción con demostración → seguir una indicación verbal → completar dos acciones consecutivas → realizar una secuencia breve sin recordatorios, si resulta cómodo.$mrc$, $mrc$Repitan la indicación con las mismas palabras. Si aún resulta difícil, divídanla y señalen el objeto o el lugar correspondiente. También pueden mostrar primero cómo hacerlo.

Preventivo: comenzar con dos acciones y aumentar gradualmente a tres, según facilidad. Invitar a repetir el plan antes de ejecutarlo.
Deterioro cognitivo leve: comenzar con una acción. Incorporar una segunda cuando la primera versión resulte cómoda. Permitir repetición y apoyos visibles.
Demencia leve: dar una instrucción concreta por vez. Mantener pocos objetos sobre la mesa y acompañar con gestos cuando sea necesario.
Demencia moderada: presentar un objeto y modelar una acción inmediata: «Pongamos la servilleta aquí». Omitir las secuencias.
Demencia severa: no utilizar la versión de retención de instrucciones. Elegir una actividad de participación acompañada en una sola acción.$mrc$, $mrc$Evitar instrucciones ambiguas, objetos peligrosos o movimientos fuera del alcance. Si la persona no realiza la acción, comprobar primero que escuchó y comprendió la indicación.$mrc$, $mrc${"gancho": "¿Sabías que utilizamos la memoria de trabajo cuando mantenemos una indicación en mente mientras la cumplimos?", "evidencia": "Por ejemplo, cuando nos piden buscar una servilleta y colocarla en la mesa.", "cierre": "Hoy vamos a practicar esa habilidad con acciones sencillas. Escuchar, repetir el plan y hacerlo por partes nos permite organizar lo que vamos a hacer. 🧠"}$mrc$::jsonb, $mrc$Facilitar que la persona mantenga una indicación breve durante el tiempo necesario para realizarla, con los apoyos que requiera.$mrc$, array['preventivo', 'dcl', 'leve', 'moderada']::text[], null, true),
  ($mrc$MRC-25$mrc$, $mrc$Un nombre, una conexión$mrc$, 'cognicion'::public.resource_modulo, 'actividad'::public.task_tipo, $mrc$atención, memoria y funciones ejecutivas$mrc$, array[$mrc$Atención al nombre$mrc$, $mrc$Asociación semántica$mrc$, $mrc$Aprendizaje de información nueva$mrc$, $mrc$Recuperación con pistas$mrc$, $mrc$Lenguaje$mrc$]::text[], $mrc$De 5 a 8 minutos.$mrc$, 5, 8, $mrc$Practicar brevemente en distintas ocasiones cuando exista un nombre útil que aprender.$mrc$, $mrc$Preventivo. · Deterioro cognitivo leve. · Demencia leve, si comprende la asociación y participa sin malestar.$mrc$, $mrc$Un nombre al inicio. Elegir referencias conocidas y respetuosas. Sustituir la asociación por un apoyo visible si genera confusión.$mrc$, $mrc$Practicar una estrategia para aprender un nombre mediante una referencia conocida y significativa.$mrc$, $mrc$Una fotografía de una persona cuyo nombre se quiera aprender. También puede utilizarse un personaje ficticio o practicar con alguien presente.$mrc$, $mrc$Hoy realizaremos «Un nombre, una conexión». Vamos a relacionar un nombre con algo conocido para tener una pista que nos ayude a recordarlo. Pueden comenzar con un solo nombre. 👤$mrc$, $mrc$["Presenten a la persona o su fotografía: «Ella se llama Rosa».", "Repitan el nombre juntos, sin exigir varias repeticiones.", "Busquen una conexión que tenga sentido para quien aprende: «Rosa, como la flor que tiene en el jardín».", "Construyan una frase breve: «Rosa, como las rosas de mi jardín».", "Utilicen el nombre en una conversación natural: «Rosa viene a acompañarnos hoy».", "Después de una pausa breve, ofrezcan la conexión como pista: «Su nombre es como una flor del jardín…».", "Si no lo recuerda, proporcionen el nombre y repitan juntos la relación."]$mrc$::jsonb, $mrc$Escuchar un nombre → relacionarlo con una referencia conocida → recuperarlo con la pista → utilizarlo en una conversación.$mrc$, $mrc$Propongan una asociación sencilla y comprueben que la comprende. Si la referencia no le resulta familiar, busquen otra o utilicen directamente una tarjeta con el nombre.

Preventivo: invitar a crear su propia asociación. Practicar un segundo nombre cuando el primero resulte familiar.
Deterioro cognitivo leve: trabajar un nombre por vez, con fotografía y frase escrita si ayuda. Mantener la misma asociación durante la práctica.
Demencia leve: el familiar propone una conexión concreta y acompaña el uso del nombre. Si la asociación confunde, utilizar la fotografía con el nombre visible.
Demencia moderada o severa: no utilizar como ejercicio de aprendizaje de nombres. Presentarse con naturalidad y aportar el nombre y el vínculo cuando sea necesario.$mrc$, $mrc$Evitar apodos o asociaciones sobre características físicas que puedan resultar incómodas. No preguntar repetidamente «¿cómo me llamo?» ni interpretar el olvido del nombre como falta de afecto.$mrc$, $mrc${"gancho": "¿Sabías que un nombre puede resultar más fácil de recordar cuando lo conectamos con algo que ya conocemos?", "evidencia": "Esa relación nos ofrece una pista: «Rosa, como la flor de mi jardín».", "cierre": "Hoy vamos a crear una conexión personal y utilizar el nombre en una conversación. La mejor pista será la que tenga sentido para la persona que está aprendiendo. 🌹🧠"}$mrc$::jsonb, $mrc$Favorecer que la persona construya y utilice una asociación como apoyo para recordar un nombre concreto.$mrc$, array['preventivo', 'dcl', 'leve']::text[], null, true),
  ($mrc$MRC-26$mrc$, $mrc$Imaginemos una escena$mrc$, 'cognicion'::public.resource_modulo, 'actividad'::public.task_tipo, $mrc$atención, memoria y funciones ejecutivas$mrc$, array[$mrc$Comprensión verbal$mrc$, $mrc$Representación mental$mrc$, $mrc$Memoria de detalles$mrc$, $mrc$Relaciones espaciales$mrc$, $mrc$Expresión oral o gráfica$mrc$]::text[], $mrc$De 5 a 10 minutos.$mrc$, 5, 10, $mrc$De 1 a 2 veces por semana.$mrc$, $mrc$Preventivo. · Deterioro cognitivo leve. · Demencia leve, si comprende descripciones breves y disfruta imaginar.$mrc$, $mrc$No exigir imágenes mentales nítidas. Comenzar con pocos elementos. Sustituir por una imagen visible si la propuesta resulta difícil.$mrc$, $mrc$Practicar la representación mental de una descripción breve y su expresión mediante palabras o dibujos.$mrc$, $mrc$Una descripción preparada por el familiar. Papel y lápices opcionales.$mrc$, $mrc$Hoy realizaremos «Imaginemos una escena». Vamos a escuchar una descripción e imaginar cómo podría verse. Cada persona puede formar una escena diferente y contarla a su manera. 🌳$mrc$, $mrc$["Busquen un espacio tranquilo y expliquen: «Voy a describir un lugar para que lo imaginemos».", "Lean despacio: «En un patio hay una mesa de madera. Encima de la mesa hay una taza azul. Junto a la mesa duerme un perro».", "Hagan una pausa para que la persona represente la escena. Puede mantener los ojos abiertos.", "Inviten a contar lo que imaginó: «¿Cómo era ese patio?» o «¿Qué había sobre la mesa?».", "Permitan que exprese la escena con palabras o un dibujo.", "Repitan la descripción cuando lo necesite y reconstruyan juntos los elementos."]$mrc$::jsonb, $mrc$Imaginar un objeto → ubicarlo en un lugar → integrar dos o tres elementos → describir una escena algo más extensa.$mrc$, $mrc$Presenten una frase por vez: «Imaginemos una mesa». Después agreguen un elemento: «Sobre la mesa hay una taza». Si imaginar no le resulta accesible, utilicen una fotografía y conversen sobre ella.

Preventivo: añadir detalles de ubicación, colores o acciones. Pedir que relate la escena con sus propias palabras o invente una continuación.
Deterioro cognitivo leve: utilizar dos o tres elementos y repetir la descripción por partes.
Demencia leve: comenzar con un objeto familiar y una ubicación sencilla. Aceptar respuestas breves y acompañar con preguntas concretas.
Demencia moderada o severa: elegir una actividad con imágenes u objetos presentes, sin exigir la construcción de una escena mental.$mrc$, $mrc$No todas las personas forman imágenes mentales con la misma facilidad. No insistir ni pedir cerrar los ojos. Evitar escenas que provoquen miedo o recuerdos desagradables.$mrc$, $mrc${"gancho": "¿Sabías que algunas personas utilizan imágenes mentales como apoyo para recordar?", "evidencia": "Imaginar una taza azul sobre una mesa permite relacionar los detalles dentro de una misma escena.", "cierre": "Hoy vamos a explorar esta estrategia escuchando una descripción breve. Podemos contar lo imaginado o dibujarlo; cada persona encontrará la forma que le resulte más cómoda. 🧠🎨"}$mrc$::jsonb, $mrc$Facilitar que la persona represente y comunique algunos elementos de una descripción breve, con repetición o apoyos cuando sean necesarios.$mrc$, array['preventivo', 'dcl', 'leve']::text[], null, true),
  ($mrc$MRC-27$mrc$, $mrc$¿Qué iba a buscar?$mrc$, 'cognicion'::public.resource_modulo, 'actividad'::public.task_tipo, $mrc$atención, memoria y funciones ejecutivas$mrc$, array[$mrc$Memoria de intenciones$mrc$, $mrc$Memoria de trabajo$mrc$, $mrc$Atención dirigida$mrc$, $mrc$Organización de una acción$mrc$, $mrc$Uso de apoyos externos$mrc$]::text[], $mrc$De 3 a 8 minutos.$mrc$, 3, 8, $mrc$Integrar en situaciones cotidianas, evitando repeticiones innecesarias.$mrc$, $mrc$Preventivo. · Deterioro cognitivo leve. · Demencia leve, con un objeto visible o una pista. · Demencia moderada, mediante una acción inmediata y acompañada.$mrc$, $mrc$Una intención por vez. Priorizar la seguridad y permitir apoyos. En demencia moderada, realizar una acción inmediata con el objeto presente.$mrc$, $mrc$Practicar una estrategia para mantener presente una intención breve mientras se busca un objeto.$mrc$, $mrc$Un objeto cotidiano seguro, como una servilleta o un estuche. Opcionalmente, una tarjeta con su nombre o fotografía.$mrc$, $mrc$Hoy realizaremos «¿Qué iba a buscar?». Vamos a practicar cómo mantener presente una tarea sencilla antes de comenzarla. Podemos decir lo que vamos a hacer y llevar una pista si la necesitamos. 🏡$mrc$, $mrc$["Elijan una acción breve y útil: «Voy a buscar una servilleta para la mesa».", "Antes de comenzar, inviten a expresar el propósito con sus propias palabras.", "Identifiquen dónde está el objeto. Al inicio, colóquenlo cerca y a la vista.", "Realicen la acción y vuelvan al punto de inicio.", "Comprueben juntos: «Fuimos a buscar la servilleta y aquí está».", "Si resulta cómodo, practiquen en otra ocasión con un objeto que esté un poco más lejos, manteniendo un recorrido seguro."]$mrc$::jsonb, $mrc$Buscar un objeto visible → repetir el propósito antes de actuar → buscarlo a corta distancia con una pista → completar la acción en otra zona conocida y segura.$mrc$, $mrc$Utilicen una tarjeta o fotografía que pueda llevar consigo. Si pierde el propósito, recuerden la acción con naturalidad: «Íbamos a buscar la servilleta para la mesa», y acompáñenla.

Preventivo: practicar una intención real y breve en otra zona de la casa. Invitar a expresar qué va a buscar y para qué, sin añadir distracciones artificiales.
Deterioro cognitivo leve: utilizar un solo objeto y una tarjeta de apoyo. Mantener un recorrido corto.
Demencia leve: elegir un objeto cercano, aportar una pista visible y acompañar cuando sea necesario.
Demencia moderada: presentar el objeto al alcance y realizar juntos una acción inmediata: «Tomemos la servilleta para la mesa». Omitir desplazamientos y pausas.
Demencia severa: no utilizar como ejercicio de mantenimiento de una intención. Elegir una acción acompañada con el objeto presente.$mrc$, $mrc$Puede realizarse completamente sentado. Evitar escaleras, superficies inestables y objetos difíciles de alcanzar. No introducir interrupciones para comprobar si la persona olvida la tarea.$mrc$, $mrc${"gancho": "¿Sabías que recordar lo que vamos a hacer también forma parte de la memoria?", "evidencia": "La utilizamos cuando nos levantamos para buscar algo o llevamos un objeto de una habitación a otra.", "cierre": "Hoy vamos a practicar cómo mantener ese propósito presente. Decirlo antes de actuar y utilizar una nota o una imagen puede servirnos de apoyo durante el recorrido. 🧠"}$mrc$::jsonb, $mrc$Facilitar que la persona complete una intención breve utilizando una frase, una señal visible o acompañamiento.$mrc$, array['preventivo', 'dcl', 'leve', 'moderada']::text[], null, true),
  ($mrc$MRC-28$mrc$, $mrc$Observo para una misión$mrc$, 'cognicion'::public.resource_modulo, 'actividad'::public.task_tipo, $mrc$atención, memoria y funciones ejecutivas$mrc$, array[$mrc$Atención selectiva$mrc$, $mrc$Comprensión verbal$mrc$, $mrc$Conocimiento del uso de los objetos$mrc$, $mrc$Razonamiento práctico$mrc$, $mrc$Expresión de decisiones$mrc$]::text[], $mrc$De 5 a 10 minutos.$mrc$, 5, 10, $mrc$De 1 a 2 veces por semana.$mrc$, $mrc$Preventivo. · Deterioro cognitivo leve. · Demencia leve. · Demencia moderada, con pocos objetos y una indicación sencilla.$mrc$, $mrc$Definir la misión antes de observar. Ajustar la cantidad de objetos y aceptar elecciones justificadas.$mrc$, $mrc$Practicar la atención dirigida mediante la búsqueda de objetos que respondan a un propósito concreto.$mrc$, $mrc$De cuatro a ocho objetos seguros, como una servilleta, una cuchara, un vaso plástico, un peine, un libro y un sombrero.$mrc$, $mrc$Hoy realizaremos «Observo para una misión». Vamos a observar varios objetos y buscar cuáles nos servirían para una tarea cotidiana. Antes de comenzar, tendremos una misión clara. 🔎$mrc$, $mrc$["Coloquen los objetos separados sobre una mesa.", "Presenten una misión: «Vamos a buscar lo que necesitamos para poner la mesa».", "Permitan que la persona observe y seleccione los elementos.", "Conversen sobre sus elecciones: «¿Cómo utilizaríamos esto?».", "Acepten respuestas diferentes cuando tengan una explicación razonable.", "Cambien la misión si la persona desea continuar: «Ahora busquemos algo que nos sirva para arreglarnos antes de salir»."]$mrc$::jsonb, $mrc$Elegir entre dos objetos → seleccionar varios elementos útiles → explicar las elecciones → proponer una misión para el familiar.$mrc$, $mrc$Reduzcan la cantidad de objetos. Ofrezcan dos opciones: «¿Para poner la mesa necesitamos la servilleta o el peine?». También pueden mostrar primero un ejemplo.

Preventivo: presentar entre seis y ocho objetos y plantear misiones que permitan distintas soluciones. Invitar a explicar qué elegiría y por qué.
Deterioro cognitivo leve: utilizar cuatro objetos y mantener la misión escrita o repetirla cuando sea necesario.
Demencia leve: elegir tareas muy familiares y presentar tres o cuatro objetos. Dar una indicación por vez.
Demencia moderada: ofrecer dos objetos claramente diferentes y pedir una elección concreta: «¿Cuál usamos para peinarnos?». Aceptar señalamiento.
Demencia severa: no utilizar la versión de selección por propósito. Preferir exploración acompañada de un objeto familiar.$mrc$, $mrc$Utilizar objetos visibles, seguros y fáciles de reconocer. Evitar convertir las elecciones en respuestas rígidamente correctas o incorrectas.$mrc$, $mrc${"gancho": "¿Sabías que tener una misión nos ayuda a orientar la atención?", "evidencia": "Cuando buscamos algo para una tarea concreta, necesitamos fijarnos en lo que resulta útil y dejar otros elementos en segundo plano.", "cierre": "Hoy vamos a observar con un propósito, elegir y explicar nuestras decisiones. Una habilidad que también utilizamos al preparar una merienda o buscar lo necesario para salir. 🔎🧠"}$mrc$::jsonb, $mrc$Facilitar que la persona seleccione uno o varios objetos de acuerdo con una finalidad cotidiana, con los apoyos necesarios.$mrc$, array['preventivo', 'dcl', 'leve', 'moderada']::text[], null, true),
  ($mrc$MRC-29$mrc$, $mrc$Un mensaje para compartir$mrc$, 'cognicion'::public.resource_modulo, 'actividad'::public.task_tipo, $mrc$atención, memoria y funciones ejecutivas$mrc$, array[$mrc$Comprensión auditiva$mrc$, $mrc$Memoria de trabajo$mrc$, $mrc$Memoria reciente$mrc$, $mrc$Identificación de ideas principales$mrc$, $mrc$Expresión oral$mrc$]::text[], $mrc$De 5 a 8 minutos.$mrc$, 5, 8, $mrc$De 1 a 2 veces por semana.$mrc$, $mrc$Preventivo. · Deterioro cognitivo leve. · Demencia leve, con mensajes sencillos y apoyos.$mrc$, $mrc$Comenzar con una idea. Permitir repetición y notas. Evitar mensajes cuya pérdida pueda generar riesgos.$mrc$, $mrc$Practicar la comprensión, el mantenimiento y la comunicación de un mensaje breve.$mrc$, $mrc$Un mensaje preparado por el familiar. Papel y lápiz opcionales.$mrc$, $mrc$Hoy realizaremos «Un mensaje para compartir». Vamos a escuchar una información breve y contarla con nuestras propias palabras. Podemos pedir que la repitan o anotar una pista. 💬$mrc$, $mrc$["Expliquen: «Voy a darle un mensaje para que después me cuente lo importante».", "Lean un mensaje sencillo: «Para la merienda de hoy vamos a poner el pan y las servilletas en la mesa».", "Pregunten: «¿Qué tenemos que preparar?».", "Permitan que lo comunique con sus propias palabras.", "Repitan juntos la información si hace falta.", "Si hay otra persona disponible y desea participar, invítenla a escuchar el mensaje. También pueden intercambiar los papeles."]$mrc$::jsonb, $mrc$Comunicar una idea inmediatamente → transmitir dos datos relacionados → utilizar una palabra clave → compartir el mensaje después de una pausa breve.$mrc$, $mrc$Dividan el mensaje: «Vamos a preparar la merienda. Necesitamos pan y servilletas». Permitan anotarlo, dibujarlo o utilizar imágenes.

Preventivo: utilizar mensajes con dos o tres datos, como qué se necesita y dónde colocarlo. Invitar a identificar lo esencial.
Deterioro cognitivo leve: comenzar con una idea principal. Permitir repetir el mensaje y utilizar una nota.
Demencia leve: comunicar una frase breve y pedir que la comparta inmediatamente. Aceptar palabras sueltas o señalamiento de los objetos.
Demencia moderada o severa: no utilizar como tarea de retención y transmisión de mensajes. Preferir comunicación inmediata sobre objetos o acciones presentes.$mrc$, $mrc$Practicar con información sin consecuencias importantes. No utilizar indicaciones sobre medicamentos, citas médicas o asuntos urgentes como prueba de recuerdo.$mrc$, $mrc${"gancho": "¿Sabías que compartir un mensaje requiere escuchar, comprender y mantener presente lo importante?", "evidencia": "No hace falta repetir cada palabra: muchas veces basta con comunicar la idea principal.", "cierre": "Hoy vamos a practicar con mensajes cotidianos. Pedir que nos repitan algo o usar una nota también son formas útiles de ayudarnos a recordar. 💬🧠"}$mrc$::jsonb, $mrc$Favorecer que la persona comunique la idea principal de un mensaje breve utilizando sus propias palabras o apoyos.$mrc$, array['preventivo', 'dcl', 'leve']::text[], null, true),
  ($mrc$MRC-30$mrc$, $mrc$Una palabra me lleva a otra$mrc$, 'cognicion'::public.resource_modulo, 'actividad'::public.task_tipo, $mrc$atención, memoria y funciones ejecutivas$mrc$, array[$mrc$Memoria semántica$mrc$, $mrc$Asociación de ideas$mrc$, $mrc$Acceso a palabras$mrc$, $mrc$Flexibilidad$mrc$, $mrc$Explicación verbal$mrc$]::text[], $mrc$De 5 a 10 minutos.$mrc$, 5, 10, $mrc$De 1 a 2 veces por semana.$mrc$, $mrc$Preventivo. · Deterioro cognitivo leve. · Demencia leve. · Demencia moderada, mediante asociaciones entre dos elementos visibles.$mrc$, $mrc$Mantener las palabras visibles si ayuda. Aceptar asociaciones personales. En demencia moderada, trabajar únicamente con dos elementos presentes.$mrc$, $mrc$Explorar relaciones entre palabras y construir una secuencia de asociaciones con significado.$mrc$, $mrc$Papel y lápiz. Opcionalmente, fotografías u objetos cotidianos.$mrc$, $mrc$Hoy realizaremos «Una palabra me lleva a otra». Vamos a descubrir cómo una idea puede conectarse con la siguiente. Cada persona puede encontrar relaciones diferentes. 🔗$mrc$, $mrc$["Comiencen con una palabra familiar: «lluvia».", "Pregunten: «¿Qué le hace pensar esa palabra?».", "Si responde «paraguas», comenten la conexión: «Usamos el paraguas cuando llueve».", "Continúen desde la nueva palabra: «¿Y paraguas con qué lo relaciona?».", "Escriban o representen la cadena: lluvia–paraguas–puerta–casa.", "Lean juntos la secuencia y conversen sobre las conexiones. Las palabras pueden permanecer visibles durante toda la actividad."]$mrc$::jsonb, $mrc$Relacionar dos elementos → construir una cadena de tres palabras → ampliar la cadena → explicar las conexiones o inventar una historia breve.$mrc$, $mrc$Ofrezcan una relación para completar: «Cuando llueve, para no mojarnos usamos…». También pueden presentar dos imágenes para elegir.

Preventivo: construir cadenas más extensas y explorar distintas asociaciones para una misma palabra.
Deterioro cognitivo leve: mantener una cadena de tres o cuatro palabras visibles y repasar cada conexión.
Demencia leve: utilizar palabras concretas, fotografías u objetos. Trabajar pocas relaciones y aportar ejemplos.
Demencia moderada: presentar dos elementos relacionados, como una taza y una cuchara, y conversar sobre cómo se utilizan juntos. Omitir la cadena.
Demencia severa: no utilizar como ejercicio de asociación verbal.$mrc$, $mrc$No imponer una única conexión. Si una respuesta no resulta clara, invitar a explicarla con curiosidad. Evitar asociaciones que generen angustia.$mrc$, $mrc${"gancho": "¿Sabías que nuestros conocimientos están conectados?", "evidencia": "La palabra «lluvia» puede hacernos pensar en un paraguas, una ventana o una tarde en casa.", "cierre": "Hoy vamos a recorrer esas conexiones. Al explicar cómo se relacionan dos palabras, utilizamos el lenguaje y los conocimientos que hemos construido a lo largo de la vida. 🔗🧠"}$mrc$::jsonb, $mrc$Facilitar que la persona establezca y comunique relaciones entre palabras u objetos, con ejemplos o apoyos visibles.$mrc$, array['preventivo', 'dcl', 'leve', 'moderada']::text[], null, true),
  ($mrc$MRC-31$mrc$, $mrc$Lo nuevo se parece a…$mrc$, 'cognicion'::public.resource_modulo, 'actividad'::public.task_tipo, $mrc$atención, memoria y funciones ejecutivas$mrc$, array[$mrc$Observación$mrc$, $mrc$Comparación$mrc$, $mrc$Memoria semántica$mrc$, $mrc$Comprensión de información nueva$mrc$, $mrc$Lenguaje descriptivo$mrc$]::text[], $mrc$De 5 a 10 minutos.$mrc$, 5, 10, $mrc$Una vez por semana o cuando surja un objeto apropiado.$mrc$, $mrc$Preventivo. · Deterioro cognitivo leve. · Demencia leve, con objetos concretos y demostración.$mrc$, $mrc$Comparar dos objetos seguros. Explicar nombre y función antes de preguntar. No exigir aprendizaje posterior.$mrc$, $mrc$Relacionar un objeto poco conocido con conocimientos previos mediante la comparación de características y funciones.$mrc$, $mrc$Un objeto seguro y poco conocido para la persona y otro familiar con alguna semejanza. Por ejemplo, un batidor de silicona y un tenedor.$mrc$, $mrc$Hoy realizaremos «Lo nuevo se parece a…». Vamos a conocer un objeto y buscar en qué se parece a otro que ya utilizamos. Observar sus semejanzas puede ayudarnos a comprender para qué sirve. 🧐$mrc$, $mrc$["Presenten el objeto poco conocido y expliquen su nombre y función.", "Permitan observarlo y manipularlo si es seguro.", "Coloquen junto a él un objeto familiar.", "Pregunten: «¿En qué se parecen?» o «¿Podemos usarlos para algo parecido?».", "Muestren una diferencia importante: «Los dos pueden mezclar, pero tienen distinta forma».", "Construyan una frase: «Este batidor se parece al tenedor porque ambos nos ayudan a mezclar».", "Cierren repasando el nombre y el uso, sin exigir que los recuerde después."]$mrc$::jsonb, $mrc$Reconocer una semejanza → identificar una diferencia → explicar el uso → relacionar otro objeto con algo conocido.$mrc$, $mrc$Señalen una característica concreta: «Los dos tienen mango». Muestren la acción y permitan imitarla.

Preventivo: elegir un objeto que despierte curiosidad y comparar forma, material, función y situaciones de uso.
Deterioro cognitivo leve: presentar una sola comparación y construir juntos una frase sencilla.
Demencia leve: utilizar un objeto solo ligeramente diferente de otro conocido. Priorizar la demostración y las características visibles.
Demencia moderada o severa: no utilizar como aprendizaje de objetos nuevos. Preferir reconocimiento y uso acompañado de objetos familiares.$mrc$, $mrc$Evitar objetos cortantes, eléctricos o que puedan confundirse con alimentos. Explicar también las diferencias: parecerse no significa que ambos puedan utilizarse de la misma manera.$mrc$, $mrc${"gancho": "¿Sabías que para comprender algo nuevo solemos buscarle un parecido con algo conocido?", "evidencia": "Comparar su forma o su función nos da un punto de partida para entenderlo.", "cierre": "Hoy vamos a utilizar esa estrategia con un objeto. Buscaremos semejanzas y diferencias para darle sentido a la información nueva. 🧠"}$mrc$::jsonb, $mrc$Facilitar que la persona identifique una semejanza o diferencia entre dos objetos y comprenda el uso del objeto presentado.$mrc$, array['preventivo', 'dcl', 'leve']::text[], null, true),
  ($mrc$MRC-32$mrc$, $mrc$Una idea, varias formas$mrc$, 'cognicion'::public.resource_modulo, 'actividad'::public.task_tipo, $mrc$atención, memoria y funciones ejecutivas$mrc$, array[$mrc$Expresión de necesidades$mrc$, $mrc$Acceso a palabras$mrc$, $mrc$Flexibilidad verbal$mrc$, $mrc$Comunicación gestual$mrc$, $mrc$Intercambio comunicativo$mrc$]::text[], $mrc$De 5 a 10 minutos; interacciones más breves en niveles avanzados.$mrc$, 5, 10, $mrc$De 1 a 2 veces por semana y en oportunidades naturales.$mrc$, $mrc$Preventivo. · Deterioro cognitivo leve. · Demencia leve. · Demencia moderada, con ejemplos y opciones concretas. · Demencia severa, mediante respuestas comunicativas habituales y acompañamiento.$mrc$, $mrc$Aceptar palabras, gestos y señalamiento. En demencia avanzada, priorizar la comunicación presente y la confirmación.$mrc$, $mrc$Explorar distintas maneras de comunicar una necesidad o una idea mediante palabras, gestos y apoyos.$mrc$, $mrc$Tarjetas con situaciones cotidianas o fotografías. También pueden utilizarse objetos, como una manta o un vaso plástico vacío.$mrc$, $mrc$Hoy realizaremos «Una idea, varias formas». Vamos a descubrir distintas maneras de expresar lo que necesitamos. Podemos usar una frase, señalar un objeto o acompañarnos con un gesto. 💬$mrc$, $mrc$["Presenten una situación: «Imaginemos que tenemos frío».", "Den un ejemplo: «Podemos decir “tengo frío”».", "Inviten a buscar otra manera: «¿Qué podríamos pedir?».", "Propongan alternativas si hace falta: «Necesito una manta» o señalarla.", "Representen brevemente el intercambio: una persona expresa la necesidad y la otra responde.", "Practiquen otra situación, como pedir ayuda para alcanzar un objeto."]$mrc$::jsonb, $mrc$Reconocer una necesidad → expresarla de una forma → explorar otra alternativa → utilizarla en un intercambio breve.$mrc$, $mrc$Muestren el objeto y ofrezcan un modelo: «¿Quiere la manta?». Acepten palabras sueltas o gestos y confirmen lo que entendieron.

Preventivo: proponer varias formas de expresar una idea y conversar sobre cuál resulta más clara en cada situación.
Deterioro cognitivo leve: trabajar una situación por vez y permitir tiempo para formular la respuesta.
Demencia leve: utilizar ejemplos concretos, objetos y frases breves. Evitar exigir una formulación distinta si ya logra comunicar la idea.
Demencia moderada: el familiar modela una frase o gesto y ofrece opciones para expresar una necesidad presente.
Demencia severa: responder a las señales habituales de la persona y confirmar su posible significado. No exigir imitación ni atribuir una intención definitiva a una señal aislada.$mrc$, $mrc$No provocar frío, sed u otra incomodidad para realizar el ejercicio. Si una respuesta es ambigua, comprobarla antes de actuar.$mrc$, $mrc${"gancho": "¿Sabías que podemos comunicar una misma necesidad de diferentes maneras?", "evidencia": "Decir «tengo frío», pedir una manta o señalarla pueden ayudarnos a expresar lo que necesitamos.", "cierre": "Hoy vamos a explorar esas alternativas. Dar tiempo, observar y confirmar lo que entendimos ayuda a que la conversación continúe, incluso cuando cuesta encontrar una palabra. 💬🧠"}$mrc$::jsonb, $mrc$Favorecer que la persona encuentre una forma accesible de expresar una idea y que el familiar reconozca y confirme su mensaje.$mrc$, array['preventivo', 'dcl', 'leve', 'moderada', 'avanzada']::text[], null, true),
  ($mrc$MRC-33$mrc$, $mrc$Busquemos una pista$mrc$, 'cognicion'::public.resource_modulo, 'actividad'::public.task_tipo, $mrc$atención, memoria y funciones ejecutivas$mrc$, array[$mrc$Memoria episódica reciente$mrc$, $mrc$Recuperación con claves$mrc$, $mrc$Asociación con el contexto$mrc$, $mrc$Atención$mrc$, $mrc$Reconocimiento$mrc$]::text[], $mrc$De 5 a 8 minutos.$mrc$, 5, 8, $mrc$De 1 a 2 veces por semana.$mrc$, $mrc$Preventivo. · Deterioro cognitivo leve. · Demencia leve, con una experiencia inmediata y apoyos.$mrc$, $mrc$Utilizar experiencias sencillas y verificables. Ofrecer apoyos progresivos y proporcionar la respuesta si no aparece.$mrc$, $mrc$Practicar el uso de claves de contexto para recuperar información de una experiencia reciente y sencilla.$mrc$, $mrc$Una actividad breve preparada por el familiar y sus elementos: por ejemplo, una imagen de un jardín y dos lápices de colores.$mrc$, $mrc$Hoy realizaremos «Busquemos una pista». Vamos a compartir una experiencia breve y después utilizar algunas pistas para recordar lo que hicimos. Podemos volver a mirar los materiales cuando lo necesitemos. 🔎$mrc$, $mrc$["Compartan una acción sencilla: observen una imagen y elijan un color que combine con ella.", "Conversen brevemente sobre otro tema.", "Inviten a retomar la experiencia: «Hace un momento elegimos un color. ¿Cuál fue?».", "Si no lo recuerda, aporten una pista concreta: «Estábamos mirando una imagen de un jardín».", "Si hace falta, muestren la imagen y después los dos lápices.", "Si el recuerdo no aparece, proporcionen la respuesta: «Elegimos el verde».", "Cierren reconstruyendo juntos lo que hicieron."]$mrc$::jsonb, $mrc$Recordar con los materiales presentes → utilizar una pista verbal → retomar la experiencia después de una pausa breve → reconocer qué tipo de pista le resultó útil.$mrc$, $mrc$Pasen pronto de la pregunta abierta al apoyo visible. No acumulen preguntas. Recordar juntos también es una forma válida de participar.

Preventivo: comenzar con una pregunta abierta y explorar después pistas sobre el lugar, el tema o la acción.
Deterioro cognitivo leve: utilizar una experiencia breve y una pausa corta. Ofrecer pistas concretas y permitir consultar los materiales.
Demencia leve: trabajar inmediatamente después de la acción. Mostrar los elementos y ofrecer dos opciones si es necesario.
Demencia moderada o severa: no utilizar como tarea de recuperación de una experiencia reciente. Preferir conversación sobre lo que está presente.$mrc$, $mrc$No utilizar recuerdos de conflictos, pérdidas o situaciones importantes. Las pistas pueden ayudar, pero no garantizan que aparezca el recuerdo. No insistir ni sugerir detalles que no ocurrieron.$mrc$, $mrc${"gancho": "¿Sabías que a veces un lugar, un objeto o un tema nos da una pista para recordar?", "evidencia": "Por eso podemos recuperar una idea al volver a mirar lo que estábamos haciendo.", "cierre": "Hoy vamos a explorar esas pistas con una experiencia sencilla. Si el recuerdo no aparece, podemos reconstruirlo juntos y continuar. 🔎🧠"}$mrc$::jsonb, $mrc$Facilitar que la persona utilice una pista verbal o visual para recordar o reconocer un detalle de una experiencia compartida.$mrc$, array['preventivo', 'dcl', 'leve']::text[], null, true),
  ($mrc$MRC-34$mrc$, $mrc$Lo hice y lo registro$mrc$, 'cognicion'::public.resource_modulo, 'actividad'::public.task_tipo, $mrc$atención, memoria y funciones ejecutivas$mrc$, array[$mrc$Atención a la acción$mrc$, $mrc$Secuenciación$mrc$, $mrc$Uso de apoyos externos$mrc$, $mrc$Comprobación de tareas$mrc$, $mrc$Organización cotidiana$mrc$]::text[], $mrc$De 5 a 8 minutos.$mrc$, 5, 8, $mrc$Practicar con una rutina sencilla, según necesidad.$mrc$, $mrc$Preventivo. · Deterioro cognitivo leve. · Demencia leve, con una lista sencilla. · Demencia moderada, mediante una acción y registro acompañados.$mrc$, $mrc$Marcar después de realizar la acción. Mantener el registro actualizado. En demencia, acompañar y verificar según capacidad.$mrc$, $mrc$Practicar el uso de un registro visible para comprobar si se realizó una acción cotidiana.$mrc$, $mrc$Una hoja con una tarea escrita o representada con una imagen, un espacio para marcar y un lápiz. Un objeto seguro para realizar la acción.$mrc$, $mrc$Hoy realizaremos «Lo hice y lo registro». Vamos a realizar una tarea sencilla y dejar una señal de que está terminada. Después podremos consultar el registro. ✅$mrc$, $mrc$["Elijan una acción sin riesgo, como guardar una revista en una cesta.", "Preparen una hoja que diga «Guardar la revista», con un espacio para marcar.", "Lean o expliquen juntos la tarea.", "Realicen la acción.", "Inmediatamente después, hagan una marca: «Ya guardamos la revista; ahora lo anotamos».", "Después de una pausa breve, consulten juntos la hoja: «Aquí podemos ver lo que ya hicimos».", "Para una nueva práctica, utilicen un registro claramente identificado como nuevo."]$mrc$::jsonb, $mrc$Realizar y marcar con ayuda → completar una tarea y consultar el registro → utilizar una lista breve de dos acciones diferenciadas.$mrc$, $mrc$Acompañen la secuencia completa: hacer la acción y marcar. Utilicen una fotografía en lugar de texto o permitan colocar una ficha grande sobre el espacio correspondiente.

Preventivo: preparar una lista de dos o tres tareas sencillas y practicar marcar únicamente después de realizarlas.
Deterioro cognitivo leve: comenzar con una sola tarea y mantener el registro cerca del lugar de la acción.
Demencia leve: utilizar una imagen y un espacio grande para marcar. El familiar comprueba que la señal corresponde a una tarea efectivamente realizada.
Demencia moderada: realizar una acción y marcar juntos inmediatamente. No exigir que consulte la hoja de manera independiente.
Demencia severa: no utilizar como sistema de seguimiento autónomo. Elegir actividades de participación directa sin exigencia de registro.$mrc$, $mrc$Practicar inicialmente con acciones sin consecuencias importantes. No utilizar este ejercicio para decidir si se repite una dosis de medicamento. Evitar hojas antiguas o marcas confusas.$mrc$, $mrc${"gancho": "¿Sabías que podemos dejar parte del trabajo de recordar en una ayuda visible?", "evidencia": "Una marca en una lista permite consultar qué hicimos sin depender únicamente del recuerdo.", "cierre": "Hoy vamos a practicar una secuencia sencilla: hacer, marcar y consultar. La señal será útil cuando represente con claridad una acción que realmente terminamos. ✅🧠"}$mrc$::jsonb, $mrc$Favorecer que la persona participe en registrar una acción realizada y consultar esa señal, con supervisión según necesidad.$mrc$, array['preventivo', 'dcl', 'leve', 'moderada']::text[], null, true),
  ($mrc$MRC-35$mrc$, $mrc$Palabras que organizan$mrc$, 'cognicion'::public.resource_modulo, 'actividad'::public.task_tipo, $mrc$atención, memoria y funciones ejecutivas$mrc$, array[$mrc$Comprensión verbal$mrc$, $mrc$Identificación de ideas principales$mrc$, $mrc$Organización de información$mrc$, $mrc$Expresión oral$mrc$, $mrc$Uso de palabras clave$mrc$]::text[], $mrc$De 5 a 10 minutos.$mrc$, 5, 10, $mrc$De 1 a 2 veces por semana.$mrc$, $mrc$Preventivo. · Deterioro cognitivo leve. · Demencia leve, con información breve y palabras visibles.$mrc$, $mrc$Mantener las pistas visibles. Ajustar la extensión y permitir participación oral, escrita o mediante imágenes.$mrc$, $mrc$Practicar la selección de palabras clave y utilizarlas para organizar una explicación breve.$mrc$, $mrc$Un texto de tres o cuatro frases, papel y lápiz. Opcionalmente, imágenes que representen las ideas principales.$mrc$, $mrc$Hoy realizaremos «Palabras que organizan». Vamos a escuchar una explicación breve, elegir sus palabras más importantes y utilizarlas como guía para contarla. 📝$mrc$, $mrc$["Lean un texto sencillo: «Para preparar una ensalada, primero lavamos los vegetales. Después los cortamos y los colocamos en un recipiente. Al final añadimos el aderezo».", "Pregunten: «¿Qué palabras nos ayudarían a explicar estos pasos?».", "Escriban juntas las palabras elegidas, por ejemplo: «lavar», «cortar», «mezclar».", "Manténganlas visibles y repasen su relación con el texto.", "Inviten a explicar la idea utilizando esas pistas.", "Vuelvan al texto cuando sea necesario. No hace falta repetirlo literalmente."]$mrc$::jsonb, $mrc$Usar una palabra como pista → organizar dos o tres ideas → elegir las palabras clave → explicar un contenido algo más extenso.$mrc$, $mrc$Ofrezcan las palabras ya preparadas o utilicen imágenes. Construyan la explicación juntos, una idea por vez.

Preventivo: utilizar un texto más amplio y permitir que seleccione sus propias palabras clave. Conversar sobre qué información puede dejar fuera sin perder el sentido.
Deterioro cognitivo leve: presentar un texto corto y elegir juntos dos o tres palabras. Mantenerlas visibles durante la explicación.
Demencia leve: trabajar con una o dos frases y apoyos preparados por el familiar. Aceptar una explicación breve o completar juntos las ideas.
Demencia moderada o severa: no utilizar como tarea de selección y resumen. Preferir palabras e imágenes vinculadas con una acción presente.$mrc$, $mrc$Elegir contenidos conocidos y acordes con la escolaridad y los intereses. Si leer o escribir resulta difícil, realizar toda la actividad oralmente o con imágenes. En el ejemplo de cocina, no es necesario manipular alimentos ni utensilios.$mrc$, $mrc${"gancho": "¿Sabías que unas pocas palabras pueden servirnos de guía para explicar una idea?", "evidencia": "Elegir lo esencial nos ayuda a organizar la información sin tener que repetir cada frase.", "cierre": "Hoy vamos a crear nuestras propias pistas y utilizarlas para contar algo con nuestras palabras. Podemos escribirlas, dibujarlas o acompañarlas con imágenes. 📝🧠"}$mrc$::jsonb, $mrc$Facilitar que la persona organice y comunique una explicación breve apoyándose en palabras o imágenes seleccionadas.$mrc$, array['preventivo', 'dcl', 'leve']::text[], null, true)
